# Round 54 -- part28 rows (28, 186)-(28, 220) except deferred 189/218; 33 items
BATCH={
  (28, 186): {
   "topic": "pretermRiskMultipleGestation",
   "lead": "\u062d\u0627\u0645\u0644\u06af\u06cc \u0633\u0647\u200c\u0642\u0644\u0648 (\u0686\u0646\u062f\u0642\u0644\u0648\u06cc\u06cc) \u0642\u0648\u06cc\u200c\u062a\u0631\u06cc\u0646 \u0639\u0627\u0645\u0644 \u062e\u0637\u0631 \u0632\u0627\u06cc\u0645\u0627\u0646 \u0632\u0648\u062f\u0631\u0633 \u062f\u0631 \u0627\u06cc\u0646 \u0641\u0647\u0631\u0633\u062a \u0627\u0633\u062a.",
   "interpretation": "\u0628\u06cc\u0634\u200c\u06a9\u0634\u06cc\u062f\u06af\u06cc (\u0627\u0648\u0631\u062f\u06cc\u0633\u062a\u0646\u0634\u0646) \u0631\u062d\u0645 \u062f\u0631 \u062d\u0627\u0645\u0644\u06af\u06cc \u0686\u0646\u062f\u0642\u0644\u0648\u06cc\u06cc\u060c \u0634\u0631\u0648\u0639 \u0632\u0648\u062f\u0631\u0633 \u0627\u0646\u0642\u0628\u0627\u0636\u0627\u062a \u0648 \u0632\u0627\u06cc\u0645\u0627\u0646 \u067e\u06cc\u0634 \u0627\u0632 \u062a\u0631\u0645 \u0631\u0627 \u0627\u0641\u0632\u0627\u06cc\u0634 \u0645\u06cc\u200c\u062f\u0647\u062f \u0648 \u0633\u0647\u200c\u0642\u0644\u0648 \u0628\u0627\u0644\u0627\u062a\u0631\u06cc\u0646 \u062e\u0637\u0631 \u0631\u0627 \u062f\u0631 \u0627\u06cc\u0646 \u0641\u0647\u0631\u0633\u062a \u062f\u0627\u0631\u062f. \u0627\u0644\u06cc\u06af\u0648\u0647\u06cc\u062f\u0631\u0627\u0645\u0646\u06cc\u0648\u0633 \u062f\u0631 \u0628\u0631\u062e\u06cc \u0645\u0648\u0627\u0631\u062f \u0628\u0627 \u0632\u0627\u06cc\u0645\u0627\u0646 \u0632\u0648\u062f\u0631\u0633 \u0647\u0645\u0631\u0627\u0647 \u0627\u0633\u062a \u0648\u0644\u06cc \u062e\u0637\u0631 \u0645\u0633\u062a\u0642\u0644 \u0622\u0646 \u0627\u0632 \u0686\u0646\u062f\u0642\u0644\u0648\u06cc\u06cc \u06a9\u0645\u200c\u062a\u0631 \u0627\u0633\u062a\u060c \u0633\u0627\u0628\u0642\u0647\u0654 \u06cc\u06a9 \u0632\u0627\u06cc\u0645\u0627\u0646 \u062a\u0631\u0645 \u0645\u062d\u0627\u0641\u0638\u062a\u06cc \u0627\u0633\u062a \u0648 \u0647\u0645\u0648\u06af\u0644\u0648\u0628\u06cc\u0646 \u06f1\u06f2 \u06af\u0631\u0645 \u062f\u0631 \u062f\u0633\u06cc\u200c\u0644\u06cc\u062a\u0631 \u062f\u0631 \u0645\u062d\u062f\u0648\u062f\u0647\u0654 \u0637\u0628\u06cc\u0639\u06cc \u0642\u0631\u0627\u0631 \u062f\u0627\u0631\u062f.",
   "reasons": ["\u0627\u0644\u06cc\u06af\u0648\u0647\u06cc\u062f\u0631\u0627\u0645\u0646\u06cc\u0648\u0633 \u062e\u0637\u0631 \u0645\u0633\u062a\u0642\u0644 \u0648 \u0642\u0648\u06cc \u0628\u0631\u0627\u06cc \u0632\u0627\u06cc\u0645\u0627\u0646 \u0632\u0648\u062f\u0631\u0633 \u0646\u0645\u06cc\u200c\u0633\u0627\u0632\u062f \u0648 \u0627\u0632 \u0686\u0646\u062f\u0642\u0644\u0648\u06cc\u06cc \u06a9\u0645\u200c\u0627\u0647\u0645\u06cc\u062a\u200c\u062a\u0631 \u0627\u0633\u062a.", "\u0633\u0627\u0628\u0642\u0647\u0654 \u06cc\u06a9 \u0632\u0627\u06cc\u0645\u0627\u0646 \u062a\u0631\u0645 \u0628\u0647\u200c\u062e\u0648\u062f\u06cc\u200c\u062e\u0648\u062f \u0639\u0627\u0645\u0644 \u062e\u0637\u0631 \u0632\u0627\u06cc\u0645\u0627\u0646 \u0632\u0648\u062f\u0631\u0633 \u0645\u062d\u0633\u0648\u0628 \u0646\u0645\u06cc\u200c\u0634\u0648\u062f.", "\u062d\u0627\u0645\u0644\u06af\u06cc \u0633\u0647\u200c\u0642\u0644\u0648 \u0628\u0627 \u0628\u06cc\u0634\u200c\u06a9\u0634\u06cc\u062f\u06af\u06cc \u0631\u062d\u0645 \u0628\u06cc\u0634\u062a\u0631\u06cc\u0646 \u062e\u0637\u0631 \u0632\u0627\u06cc\u0645\u0627\u0646 \u0632\u0648\u062f\u0631\u0633 \u0631\u0627 \u062f\u0627\u0631\u062f\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0647\u0645\u0648\u06af\u0644\u0648\u0628\u06cc\u0646 \u06f1\u06f2 \u06af\u0631\u0645 \u062f\u0631 \u062f\u0633\u06cc\u200c\u0644\u06cc\u062a\u0631 \u0637\u0628\u06cc\u0639\u06cc \u0627\u0633\u062a \u0648 \u062e\u0637\u0631 \u0632\u0627\u06cc\u0645\u0627\u0646 \u0632\u0648\u062f\u0631\u0633 \u0627\u06cc\u062c\u0627\u062f \u0646\u0645\u06cc\u200c\u06a9\u0646\u062f."],
  },
  (28, 187): {
   "topic": "delayedMensesFirstBhcg",
   "lead": "\u062a\u0623\u062e\u06cc\u0631 \u0642\u0627\u0639\u062f\u06af\u06cc \u062f\u0631 \u0632\u0646\u06cc \u0628\u0627 \u0631\u0648\u0634 \u067e\u06cc\u0634\u06af\u06cc\u0631\u06cc \u0646\u0627\u0645\u0637\u0645\u0626\u0646: \u0627\u0648\u0644\u06cc\u0646 \u0627\u0642\u062f\u0627\u0645 \u0627\u0646\u062f\u0627\u0632\u0647\u200c\u06af\u06cc\u0631\u06cc BHCG \u0627\u0633\u062a.",
   "interpretation": "\u062f\u0631 \u0632\u0646\u06cc \u06a9\u0647 \u0628\u0627 \u062a\u0623\u062e\u06cc\u0631 \u0642\u0627\u0639\u062f\u06af\u06cc \u0648 \u0628\u062f\u0648\u0646 \u0631\u0648\u0634 \u067e\u06cc\u0634\u06af\u06cc\u0631\u06cc \u0645\u0637\u0645\u0626\u0646 \u0645\u0631\u0627\u062c\u0639\u0647 \u0645\u06cc\u200c\u06a9\u0646\u062f\u060c \u067e\u06cc\u0634 \u0627\u0632 \u0647\u0631 \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u0647\u0648\u0631\u0645\u0648\u0646\u06cc \u062f\u06cc\u06af\u0631 \u0628\u0627\u06cc\u062f \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0631\u062f \u06cc\u0627 \u062a\u0623\u06cc\u06cc\u062f \u0634\u0648\u062f \u0648 \u0633\u0631\u06cc\u0639\u200c\u062a\u0631\u06cc\u0646 \u0648 \u06a9\u0645\u200c\u0647\u0632\u06cc\u0646\u0647\u200c\u062a\u0631\u06cc\u0646 \u0631\u0627\u0647\u060c \u0627\u0646\u062f\u0627\u0632\u0647\u200c\u06af\u06cc\u0631\u06cc BHCG \u0627\u0633\u062a. \u0647\u0648\u0631\u0645\u0648\u0646 \u0645\u062d\u0631\u06a9 \u0641\u0648\u0644\u06cc\u06a9\u0648\u0644 (FSH) \u062f\u0631 \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u0630\u062e\u06cc\u0631\u0647\u0654 \u062a\u062e\u0645\u062f\u0627\u0646 \u0648 \u0627\u062e\u062a\u0644\u0627\u0644 \u062a\u062e\u0645\u06a9\u200c\u06af\u0630\u0627\u0631\u06cc\u060c TSH \u062f\u0631 \u0639\u0644\u0644 \u062a\u06cc\u0631\u0648\u0626\u06cc\u062f\u06cc \u0627\u062e\u062a\u0644\u0627\u0644 \u0642\u0627\u0639\u062f\u06af\u06cc \u0648 \u067e\u0631\u0648\u0644\u0627\u06a9\u062a\u06cc\u0646 \u062f\u0631 \u0622\u0645\u0646\u0648\u0631\u0647 \u06cc\u0627 \u06af\u0627\u0644\u0627\u06a9\u062a\u0648\u0631\u0647 \u0628\u0631\u0631\u0633\u06cc \u0645\u06cc\u200c\u0634\u0648\u0646\u062f \u0648 \u062f\u0631 \u0627\u06cc\u0646 \u0645\u0631\u062d\u0644\u0647 \u0627\u0648\u0644\u0648\u06cc\u062a \u0646\u062f\u0627\u0631\u0646\u062f.",
   "reasons": ["FSH \u0645\u0631\u0628\u0648\u0637 \u0628\u0647 \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u0630\u062e\u06cc\u0631\u0647\u0654 \u062a\u062e\u0645\u062f\u0627\u0646 \u0648 \u0627\u062e\u062a\u0644\u0627\u0644 \u062a\u062e\u0645\u06a9\u200c\u06af\u0630\u0627\u0631\u06cc \u0627\u0633\u062a \u0648 \u0642\u062f\u0645 \u0627\u0648\u0644 \u0627\u06cc\u0646 \u0628\u06cc\u0645\u0627\u0631 \u0646\u06cc\u0633\u062a.", "TSH \u062f\u0631 \u0628\u0631\u0631\u0633\u06cc \u0639\u0644\u0644 \u062a\u06cc\u0631\u0648\u0626\u06cc\u062f\u06cc \u0627\u062e\u062a\u0644\u0627\u0644 \u0642\u0627\u0639\u062f\u06af\u06cc \u062c\u0627\u06cc \u062f\u0627\u0631\u062f \u0646\u0647 \u062f\u0631 \u06af\u0627\u0645 \u0646\u062e\u0633\u062a \u0627\u06cc\u0646 \u0628\u06cc\u0645\u0627\u0631.", "\u067e\u0631\u0648\u0644\u0627\u06a9\u062a\u06cc\u0646 \u062f\u0631 \u0622\u0645\u0646\u0648\u0631\u0647 \u06cc\u0627 \u06af\u0627\u0644\u0627\u06a9\u062a\u0648\u0631\u0647 \u0628\u0631\u0631\u0633\u06cc \u0645\u06cc\u200c\u0634\u0648\u062f \u0648 \u0627\u06cc\u0646\u200c\u062c\u0627 \u0627\u0648\u0644\u0648\u06cc\u062a \u0627\u0648\u0644 \u0646\u06cc\u0633\u062a.", "\u0627\u0646\u062f\u0627\u0632\u0647\u200c\u06af\u06cc\u0631\u06cc BHCG \u0628\u0631\u0627\u06cc \u0631\u062f \u06cc\u0627 \u062a\u0623\u06cc\u06cc\u062f \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0627\u0648\u0644\u06cc\u0646 \u0627\u0642\u062f\u0627\u0645 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d."],
  },
  (28, 188): {
   "topic": "severePreeclampsiaAdmitLdr",
   "lead": "\u067e\u0631\u0641\u0634\u0627\u0631\u06cc \u06f1\u06f7\u06f0/\u06f1\u06f1\u06f0 \u0647\u0645\u0631\u0627\u0647 \u067e\u0631\u0648\u062a\u0626\u06cc\u0646\u0648\u0631\u06cc \u0633\u0647 \u0645\u062b\u0628\u062a \u0648 \u0633\u0631\u062f\u0631\u062f \u062f\u0631 \u06f2\u06f8 \u0647\u0641\u062a\u0647: \u0628\u0633\u062a\u0631\u06cc \u062f\u0631 \u0627\u062a\u0627\u0642 \u0632\u0627\u06cc\u0645\u0627\u0646.",
   "interpretation": "\u06af\u0631\u0647\u0654 \u0627\u0635\u0644\u06cc \u067e\u0631\u0647\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u0634\u062f\u06cc\u062f\u060c \u062a\u0635\u0645\u06cc\u0645\u200c\u06af\u06cc\u0631\u06cc \u062f\u0631\u0628\u0627\u0631\u0647\u0654 \u062e\u062a\u0645 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0648 \u067e\u0627\u06cc\u0634 \u0645\u0633\u062a\u0645\u0631 \u0645\u0627\u062f\u0631 \u0648 \u062c\u0646\u06cc\u0646 \u0627\u0633\u062a \u0648 \u0627\u06cc\u0646 \u06a9\u0627\u0631 \u062f\u0631 \u0627\u062a\u0627\u0642 \u0632\u0627\u06cc\u0645\u0627\u0646 \u0627\u0646\u062c\u0627\u0645 \u0645\u06cc\u200c\u0634\u0648\u062f\u061b \u0628\u06cc\u0645\u0627\u0631 \u0622\u0646\u200c\u0642\u062f\u0631 \u0628\u062f\u062d\u0627\u0644 \u0646\u06cc\u0633\u062a \u06a9\u0647 \u0628\u0647 \u0645\u0631\u0627\u0642\u0628\u062a \u0648\u06cc\u0698\u0647 \u0646\u06cc\u0627\u0632 \u062f\u0627\u0634\u062a\u0647 \u0628\u0627\u0634\u062f. \u0628\u062e\u0634 \u0645\u0631\u0627\u0642\u0628\u062a\u200c\u0647\u0627\u06cc \u0642\u0644\u0628 \u0628\u0631\u0627\u06cc \u0628\u06cc\u0645\u0627\u0631\u0627\u0646 \u0642\u0644\u0628\u06cc \u06a9\u0627\u0631\u0628\u0631\u062f \u062f\u0627\u0631\u062f \u0648 \u0628\u062e\u0634 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u067e\u0631\u062e\u0637\u0631 \u0628\u0631\u0627\u06cc \u067e\u0627\u06cc\u0634 \u0637\u0648\u0644\u0627\u0646\u06cc\u200c\u0645\u062f\u062a \u0628\u062f\u0648\u0646 \u0628\u0631\u0646\u0627\u0645\u0647\u0654 \u062e\u062a\u0645 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u06a9\u0627\u0641\u06cc \u0646\u06cc\u0633\u062a.",
   "reasons": ["\u0628\u062e\u0634 \u0645\u0631\u0627\u0642\u0628\u062a \u0648\u06cc\u0698\u0647 \u0628\u0631\u0627\u06cc \u0646\u0627\u067e\u0627\u06cc\u062f\u0627\u0631\u06cc \u0634\u062f\u06cc\u062f \u06cc\u0627 \u0646\u06cc\u0627\u0632 \u0628\u0647 \u062a\u0647\u0648\u06cc\u0647 \u0648 \u062d\u0645\u0627\u06cc\u062a \u0627\u0631\u06af\u0627\u0646\u200c\u0647\u0627\u0633\u062a \u0648 \u0627\u06cc\u0646\u200c\u062c\u0627 \u0627\u0648\u0644\u0648\u06cc\u062a \u0646\u062f\u0627\u0631\u062f.", "\u0627\u062a\u0627\u0642 \u0632\u0627\u06cc\u0645\u0627\u0646 \u0645\u062d\u0644 \u06a9\u0646\u062a\u0631\u0644 \u0641\u0634\u0627\u0631\u060c \u067e\u0627\u06cc\u0634 \u062c\u0646\u06cc\u0646 \u0648 \u062e\u062a\u0645 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0628\u062e\u0634 \u0645\u0631\u0627\u0642\u0628\u062a\u200c\u0647\u0627\u06cc \u0642\u0644\u0628 \u0645\u062e\u0635\u0648\u0635 \u0628\u06cc\u0645\u0627\u0631\u0627\u0646 \u0642\u0644\u0628\u06cc \u0627\u0633\u062a \u0648 \u0628\u0631\u0627\u06cc \u0627\u06cc\u0646 \u0628\u06cc\u0645\u0627\u0631 \u0627\u0646\u062f\u06cc\u06a9\u0627\u0633\u06cc\u0648\u0646 \u0646\u062f\u0627\u0631\u062f.", "\u0628\u062e\u0634 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u067e\u0631\u062e\u0637\u0631 \u0628\u0631\u0627\u06cc \u067e\u0627\u06cc\u0634 \u0637\u0648\u0644\u0627\u0646\u06cc\u200c\u0645\u062f\u062a \u0628\u062f\u0648\u0646 \u062a\u0635\u0645\u06cc\u0645 \u0628\u0647 \u062e\u062a\u0645 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062f\u0631 \u0627\u06cc\u0646 \u0648\u0636\u0639\u06cc\u062a \u06a9\u0627\u0641\u06cc \u0646\u06cc\u0633\u062a."],
  },
  (28, 190): {
   "topic": "prenatalRubellaScreening",
   "lead": "\u062f\u0631 \u0627\u0648\u0644\u06cc\u0646 \u0648\u06cc\u0632\u06cc\u062a \u0628\u0627\u0631\u062f\u0627\u0631\u06cc\u060c \u0628\u0631\u0631\u0633\u06cc \u0622\u0646\u062a\u06cc\u200c\u0628\u0627\u062f\u06cc \u0633\u0631\u062e\u062c\u0647 (\u0631\u0648\u0628\u0644\u0627) \u062c\u0632\u0621 \u0622\u0632\u0645\u0627\u06cc\u0634\u200c\u0647\u0627\u06cc \u0631\u0648\u062a\u06cc\u0646 \u0627\u0633\u062a.",
   "interpretation": "\u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u0631\u0648\u062a\u06cc\u0646 \u067e\u06cc\u0634 \u0627\u0632 \u0632\u0627\u06cc\u0645\u0627\u0646 \u0634\u0627\u0645\u0644 \u06af\u0631\u0648\u0647 \u062e\u0648\u0646\u06cc \u0648 Rh\u060c \u06a9\u0645\u200c\u062e\u0648\u0646\u06cc\u060c \u0633\u0631\u062e\u062c\u0647 (\u0627\u06cc\u0645\u0646\u06cc)\u060c \u0633\u06cc\u0641\u0644\u06cc\u0633\u060c \u0647\u067e\u0627\u062a\u06cc\u062a B \u0648 HIV \u0627\u0633\u062a\u061b \u0633\u0631\u062e\u062c\u0647 \u0627\u0647\u0645\u06cc\u062a \u062f\u0627\u0631\u062f \u0686\u0648\u0646 \u062f\u0631 \u0632\u0646 \u063a\u06cc\u0631\u0627\u06cc\u0645\u0646 \u0628\u0627\u06cc\u062f \u067e\u0633 \u0627\u0632 \u0632\u0627\u06cc\u0645\u0627\u0646 \u0648\u0627\u06a9\u0633\u0646 \u0632\u062f\u0647 \u0634\u0648\u062f. \u062a\u0648\u06a9\u0633\u0648\u067e\u0644\u0627\u0633\u0645\u0648\u0632\u060c \u0633\u06cc\u062a\u0648\u0645\u06af\u0627\u0644\u0648\u0648\u06cc\u0631\u0648\u0633 \u0648 \u0647\u0631\u067e\u0633 \u0633\u06cc\u0645\u067e\u0644\u06a9\u0633 \u062f\u0631 \u0647\u0645\u0647\u0654 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc\u200c\u0647\u0627 \u0628\u0647\u200c\u0637\u0648\u0631 \u0631\u0648\u062a\u06cc\u0646 \u0628\u0631\u0631\u0633\u06cc \u0646\u0645\u06cc\u200c\u0634\u0648\u0646\u062f \u0648 \u0628\u06cc\u0634\u062a\u0631 \u062f\u0631 \u0645\u0648\u0627\u0631\u062f \u0628\u0627\u0644\u06cc\u0646\u06cc \u0645\u0634\u06a9\u0648\u06a9 \u06cc\u0627 \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u063a\u06cc\u0631\u0637\u0628\u06cc\u0639\u06cc \u062f\u0631\u062e\u0648\u0627\u0633\u062a \u0645\u06cc\u200c\u0634\u0648\u0646\u062f.",
   "reasons": ["\u0628\u0631\u0631\u0633\u06cc \u0631\u0648\u062a\u06cc\u0646 \u062a\u0648\u06a9\u0633\u0648\u067e\u0644\u0627\u0633\u0645\u0648\u0632 \u062f\u0631 \u0647\u0645\u0647\u0654 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc\u200c\u0647\u0627 \u062a\u0648\u0635\u06cc\u0647 \u0646\u0645\u06cc\u200c\u0634\u0648\u062f.", "\u0622\u0646\u062a\u06cc\u200c\u0628\u0627\u062f\u06cc \u0633\u0631\u062e\u062c\u0647 (\u0631\u0648\u0628\u0644\u0627) \u062c\u0632\u0621 \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u0631\u0648\u062a\u06cc\u0646 \u0627\u0648\u0644\u06cc\u0646 \u0648\u06cc\u0632\u06cc\u062a \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0633\u06cc\u062a\u0648\u0645\u06af\u0627\u0644\u0648\u0648\u06cc\u0631\u0648\u0633 \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u0631\u0648\u062a\u06cc\u0646 \u0646\u062f\u0627\u0631\u062f \u0648 \u062f\u0631 \u0645\u0648\u0627\u0631\u062f \u0645\u0634\u06a9\u0648\u06a9 \u0628\u0631\u0631\u0633\u06cc \u0645\u06cc\u200c\u0634\u0648\u062f.", "\u0647\u0631\u067e\u0633 \u0633\u06cc\u0645\u067e\u0644\u06a9\u0633 \u0628\u0631\u0631\u0633\u06cc \u0631\u0648\u062a\u06cc\u0646 \u067e\u06cc\u0634 \u0627\u0632 \u0632\u0627\u06cc\u0645\u0627\u0646 \u0646\u06cc\u0633\u062a."],
  },
  (28, 191): {
   "topic": "trisomy21RecurrenceKaryotype",
   "lead": "\u0628\u0627 \u0633\u0627\u0628\u0642\u0647\u0654 \u0641\u0631\u0632\u0646\u062f \u0645\u0628\u062a\u0644\u0627 \u0628\u0647 \u062a\u0631\u06cc\u0632\u0648\u0645\u06cc \u06f2\u06f1\u060c \u0628\u0631\u0631\u0633\u06cc \u06a9\u0627\u0631\u06cc\u0648\u062a\u0627\u06cc\u067e \u062c\u0646\u06cc\u0646 (\u062a\u0634\u062e\u06cc\u0635\u06cc) \u062a\u0648\u0635\u06cc\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f.",
   "interpretation": "\u0633\u0627\u0628\u0642\u0647\u0654 \u0641\u0631\u0632\u0646\u062f \u0642\u0628\u0644\u06cc \u0628\u0627 \u062a\u0631\u06cc\u0632\u0648\u0645\u06cc \u06f2\u06f1 \u062e\u0637\u0631 \u0628\u0627\u0632\u06af\u0634\u062a \u0631\u0627 \u0628\u0647 \u062d\u062f\u0648\u062f \u06cc\u06a9 \u062f\u0631\u0635\u062f \u0645\u06cc\u200c\u0631\u0633\u0627\u0646\u062f \u0648 \u0627\u06cc\u0646 \u062e\u0627\u0646\u0645 \u062f\u0631 \u06af\u0631\u0648\u0647 \u067e\u0631\u062e\u0637\u0631 \u0642\u0631\u0627\u0631 \u0645\u06cc\u200c\u06af\u06cc\u0631\u062f\u061b \u062f\u0631 \u06af\u0631\u0648\u0647 \u067e\u0631\u062e\u0637\u0631\u060c \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u062a\u0631\u06a9\u06cc\u0628\u06cc \u06a9\u0627\u0641\u06cc \u0646\u06cc\u0633\u062a \u0648 \u062a\u0634\u062e\u06cc\u0635 \u0642\u0637\u0639\u06cc \u0628\u0627 \u0646\u0645\u0648\u0646\u0647\u200c\u06af\u06cc\u0631\u06cc \u0627\u0632 \u067e\u0631\u0632\u0647\u0627\u06cc \u06a9\u0648\u0631\u06cc\u0648\u0646\u06cc (CVS) \u062f\u0631 \u0647\u0645\u06cc\u0646 \u0647\u0641\u062a\u0647\u200c\u0647\u0627 \u06cc\u0627 \u0622\u0645\u0646\u06cc\u0648\u0633\u0646\u062a\u0632 \u0644\u0627\u0632\u0645 \u0627\u0633\u062a. \u0645\u0634\u0631\u0648\u0637\u200c\u06a9\u0631\u062f\u0646 \u0627\u0642\u062f\u0627\u0645 \u062a\u0634\u062e\u06cc\u0635\u06cc \u0628\u0647 \u063a\u06cc\u0631\u0637\u0628\u06cc\u0639\u06cc \u0628\u0648\u062f\u0646 \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc\u060c \u062a\u0634\u062e\u06cc\u0635 \u0631\u0627 \u062f\u0631 \u0627\u06cc\u0646 \u06af\u0631\u0648\u0647 \u0628\u0647 \u062a\u0623\u062e\u06cc\u0631 \u0645\u06cc\u200c\u0627\u0646\u062f\u0627\u0632\u062f.",
   "reasons": ["\u0645\u062d\u062f\u0648\u062f\u06a9\u0631\u062f\u0646 \u0646\u0645\u0648\u0646\u0647\u200c\u06af\u06cc\u0631\u06cc \u0627\u0632 \u067e\u0631\u0632\u0647\u0627\u06cc \u06a9\u0648\u0631\u06cc\u0648\u0646\u06cc \u0628\u0647 \u0646\u062a\u06cc\u062c\u0647\u0654 \u063a\u06cc\u0631\u0637\u0628\u06cc\u0639\u06cc \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc\u060c \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u06af\u0631\u0648\u0647 \u067e\u0631\u062e\u0637\u0631 \u0646\u06cc\u0633\u062a.", "\u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u0633\u0647\u200c\u0645\u0627\u0647\u0647\u0654 \u0627\u0648\u0644 \u0628\u0631\u0627\u06cc \u06af\u0631\u0648\u0647 \u067e\u0631\u062e\u0637\u0631 \u06a9\u0627\u0641\u06cc \u0646\u06cc\u0633\u062a \u0648 \u062a\u0634\u062e\u06cc\u0635 \u0642\u0637\u0639\u06cc \u0644\u0627\u0632\u0645 \u0627\u0633\u062a.", "\u0648\u0627\u0628\u0633\u062a\u0647\u200c\u06a9\u0631\u062f\u0646 \u0622\u0645\u0646\u06cc\u0648\u0633\u0646\u062a\u0632 \u0628\u0647 \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u063a\u06cc\u0631\u0637\u0628\u06cc\u0639\u06cc\u060c \u062a\u0634\u062e\u06cc\u0635 \u0631\u0627 \u0628\u0647 \u062a\u0623\u062e\u06cc\u0631 \u0645\u06cc\u200c\u0627\u0646\u062f\u0627\u0632\u062f.", "\u062f\u0631 \u06af\u0631\u0648\u0647 \u067e\u0631\u062e\u0637\u0631 \u0628\u0631\u0631\u0633\u06cc \u06a9\u0627\u0631\u06cc\u0648\u062a\u0627\u06cc\u067e \u062c\u0646\u06cc\u0646 (\u062a\u0634\u062e\u06cc\u0635\u06cc) \u062a\u0648\u0635\u06cc\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d."],
  },
  (28, 192): {
   "topic": "breechSingleFootling",
   "lead": "\u0646\u0645\u0627\u06cc\u0634 \u0628\u0631\u06cc\u0686 \u0628\u0627 \u062f\u0631\u06af\u06cc\u0631\u06cc \u06cc\u06a9 \u067e\u0627 \u0648 \u0632\u0627\u0646\u0648\u06cc \u0646\u0627\u06a9\u0627\u0645\u0644 \u062a\u0627 \u0634\u062f\u0647: \u0646\u0645\u0627\u06cc\u0634 \u067e\u0627\u0686\u0647\u0654 \u06cc\u06a9\u200c\u0637\u0631\u0641\u0647 (Single footling).",
   "interpretation": "\u062f\u0631 \u0646\u0645\u0627\u06cc\u0634 \u0628\u0631\u06cc\u0686\u060c \u0627\u06af\u0631 \u06cc\u06a9 \u06cc\u0627 \u0647\u0631 \u062f\u0648 \u0645\u0641\u0635\u0644 \u0647\u06cc\u067e \u0628\u0627\u0632 \u0648 \u0632\u0627\u0646\u0648 \u062e\u0645 \u0646\u0634\u062f\u0647 \u0628\u0627\u0634\u062f\u060c \u067e\u0627 \u062f\u0631 \u067e\u0627\u06cc\u06cc\u0646\u200c\u062a\u0631\u06cc\u0646 \u0642\u0633\u0645\u062a \u0642\u0631\u0627\u0631 \u0645\u06cc\u200c\u06af\u06cc\u0631\u062f\u061b \u062f\u0631\u06af\u06cc\u0631\u06cc \u06cc\u06a9 \u0627\u0646\u062f\u0627\u0645 \u062a\u062d\u062a\u0627\u0646\u06cc \u00ab\u067e\u0627\u0686\u0647\u0654 \u06cc\u06a9\u200c\u0637\u0631\u0641\u0647\u00bb (Single footling) \u0648 \u062f\u0631\u06af\u06cc\u0631\u06cc \u0647\u0631 \u062f\u0648 \u067e\u0627 \u00ab\u067e\u0627\u0686\u0647\u0654 \u062f\u0648\u0637\u0631\u0641\u0647\u00bb (Double footling) \u0646\u0627\u0645\u06cc\u062f\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f. \u062f\u0631 \u0646\u0645\u0627\u06cc\u0634 \u0628\u0631\u06cc\u0686 \u0628\u0627\u0633\u0646\u06cc (Frank) \u0647\u0631 \u062f\u0648 \u0647\u06cc\u067e \u062e\u0645 \u0648 \u0632\u0627\u0646\u0648\u0647\u0627 \u06a9\u0634\u06cc\u062f\u0647\u200c\u0627\u0646\u062f \u0648 \u0628\u0627\u0633\u0646 \u067e\u0627\u06cc\u06cc\u0646\u200c\u062a\u0631\u06cc\u0646 \u0628\u062e\u0634 \u0627\u0633\u062a \u0648 \u062f\u0631 \u0628\u0631\u06cc\u0686 \u06a9\u0627\u0645\u0644 (Complete) \u0647\u0631 \u062f\u0648 \u0647\u06cc\u067e \u0648 \u0647\u0631 \u062f\u0648 \u0632\u0627\u0646\u0648 \u062e\u0645\u200c\u0634\u062f\u0647\u200c\u0627\u0646\u062f.",
   "reasons": ["\u062f\u0631 \u0628\u0631\u06cc\u0686 \u06a9\u0627\u0645\u0644 \u0647\u0631 \u062f\u0648 \u0647\u06cc\u067e \u0648 \u0647\u0631 \u062f\u0648 \u0632\u0627\u0646\u0648 \u062e\u0645\u200c\u0634\u062f\u0647\u200c\u0627\u0646\u062f\u060c \u0646\u0647 \u06cc\u06a9 \u0627\u0646\u062f\u0627\u0645.", "\u0628\u0627 \u062f\u0631\u06af\u06cc\u0631\u06cc \u06cc\u06a9 \u0627\u0646\u062f\u0627\u0645 \u062a\u062d\u062a\u0627\u0646\u06cc \u0648 \u0632\u0627\u0646\u0648\u06cc \u0646\u0627\u06a9\u0627\u0645\u0644\u060c \u067e\u0627\u0686\u0647\u0654 \u06cc\u06a9\u200c\u0637\u0631\u0641\u0647 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u067e\u0627\u0686\u0647\u0654 \u062f\u0648\u0637\u0631\u0641\u0647 \u0645\u0633\u062a\u0644\u0632\u0645 \u062f\u0631\u06af\u06cc\u0631\u06cc \u0647\u0631 \u062f\u0648 \u067e\u0627 \u0627\u0633\u062a.", "\u062f\u0631 \u0628\u0631\u06cc\u0686 \u0628\u0627\u0633\u0646\u06cc\u060c \u0628\u0627\u0633\u0646 \u067e\u0627\u06cc\u06cc\u0646\u200c\u062a\u0631\u06cc\u0646 \u0628\u062e\u0634 \u0627\u0633\u062a \u0648 \u067e\u0627 \u062f\u0631 \u067e\u0627\u06cc\u06cc\u0646 \u0642\u0631\u0627\u0631 \u0646\u0645\u06cc\u200c\u06af\u06cc\u0631\u062f."],
  },
  (28, 193): {
   "topic": "idiopathicHirsutism",
   "lead": "\u0647\u06cc\u0631\u0633\u0648\u062a\u06cc\u0633\u0645 \u0628\u0627 \u0633\u06cc\u06a9\u0644 \u0645\u0646\u0638\u0645 \u0648 \u0622\u0646\u062f\u0631\u0648\u0698\u0646 \u0648 \u062a\u062e\u0645\u06a9\u200c\u06af\u0630\u0627\u0631\u06cc \u0637\u0628\u06cc\u0639\u06cc: \u0647\u06cc\u0631\u0633\u0648\u062a\u06cc\u0633\u0645 \u0627\u06cc\u062f\u06cc\u0648\u067e\u0627\u062a\u06cc\u06a9.",
   "interpretation": "\u0648\u0642\u062a\u06cc \u067e\u0631\u0648\u0641\u0627\u06cc\u0644 \u0622\u0646\u062f\u0631\u0648\u0698\u0646\u06cc \u0648 \u062a\u062e\u0645\u062f\u0627\u0646\u06cc \u0648 \u0622\u062f\u0631\u0646\u0627\u0644 \u0637\u0628\u06cc\u0639\u06cc \u0627\u0633\u062a\u060c \u0633\u06cc\u06a9\u0644\u200c\u0647\u0627 \u0645\u0646\u0638\u0645\u200c\u0627\u0646\u062f \u0648 \u067e\u0631\u0648\u0698\u0633\u062a\u0631\u0648\u0646 \u0645\u06cc\u062f\u0644\u0648\u062a\u0626\u0627\u0644 (\u062d\u062f\u0648\u062f \u062f\u0647 \u0646\u0627\u0646\u0648\u06af\u0631\u0645 \u0628\u0631 \u0645\u06cc\u0644\u06cc\u200c\u0644\u06cc\u062a\u0631) \u062a\u062e\u0645\u06a9\u200c\u06af\u0630\u0627\u0631\u06cc \u0631\u0627 \u062a\u0623\u06cc\u06cc\u062f \u0645\u06cc\u200c\u06a9\u0646\u062f\u060c \u0647\u06cc\u0631\u0633\u0648\u062a\u06cc\u0633\u0645 \u0628\u06cc\u0634\u062a\u0631 \u00ab\u0627\u06cc\u062f\u06cc\u0648\u067e\u0627\u062a\u06cc\u06a9\u00bb \u0627\u0633\u062a \u0648 \u0628\u0647 \u062d\u0633\u0627\u0633\u06cc\u062a \u0627\u0641\u0632\u0627\u06cc\u0634\u200c\u06cc\u0627\u0641\u062a\u0647\u0654 \u0641\u0648\u0644\u06cc\u06a9\u0648\u0644 \u0645\u0648 \u0628\u0647 \u0622\u0646\u062f\u0631\u0648\u0698\u0646\u200c\u0647\u0627 \u0646\u0633\u0628\u062a \u062f\u0627\u062f\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f. \u062f\u0631 \u0633\u0646\u062f\u0631\u0645 \u062a\u062e\u0645\u062f\u0627\u0646 \u067e\u0644\u06cc\u200c\u06a9\u06cc\u0633\u062a\u06cc\u06a9 \u0642\u0627\u0639\u062f\u06af\u06cc \u0646\u0627\u0645\u0646\u0638\u0645 \u0648 \u0622\u0646\u062f\u0631\u0648\u0698\u0646\u200c\u0647\u0627 \u0628\u0627\u0644\u0627 \u0647\u0633\u062a\u0646\u062f\u060c \u062f\u0631 \u0647\u0627\u06cc\u067e\u0631\u067e\u0644\u0627\u0632\u06cc \u0622\u062f\u0631\u0646\u0627\u0644 \u0646\u0627\u06a9\u0644\u0627\u0633\u06cc\u06a9 \u06f1\u06f7-\u0647\u06cc\u062f\u0631\u0648\u06a9\u0633\u06cc\u200c\u067e\u0631\u0648\u0698\u0633\u062a\u0631\u0648\u0646 \u0628\u0627\u0644\u0627 \u0645\u06cc\u200c\u0622\u06cc\u062f \u0648 \u0633\u0646\u062f\u0631\u0645 HAIR-AN \u0628\u0627 \u0645\u0642\u0627\u0648\u0645\u062a \u0634\u062f\u06cc\u062f \u0628\u0647 \u0627\u0646\u0633\u0648\u0644\u06cc\u0646 \u0648 \u0622\u06a9\u0627\u0646\u062a\u0648\u0632\u06cc\u0633 \u0646\u06cc\u06af\u0631\u06cc\u06a9\u0627\u0646\u0633 \u0647\u0645\u0631\u0627\u0647 \u0627\u0633\u062a.",
   "reasons": ["\u062f\u0631 \u0633\u0646\u062f\u0631\u0645 \u062a\u062e\u0645\u062f\u0627\u0646 \u067e\u0644\u06cc\u200c\u06a9\u06cc\u0633\u062a\u06cc\u06a9 \u0645\u0639\u0645\u0648\u0644\u0627\u064b \u0642\u0627\u0639\u062f\u06af\u06cc \u0646\u0627\u0645\u0646\u0638\u0645 \u0648 \u0622\u0646\u062f\u0631\u0648\u0698\u0646 \u0628\u0627\u0644\u0627 \u0627\u0633\u062a.", "\u0633\u0646\u062f\u0631\u0645 HAIR-AN \u0628\u0627 \u0645\u0642\u0627\u0648\u0645\u062a \u0634\u062f\u06cc\u062f \u0628\u0647 \u0627\u0646\u0633\u0648\u0644\u06cc\u0646 \u0648 \u0622\u06a9\u0627\u0646\u062a\u0648\u0632\u06cc\u0633 \u0646\u06cc\u06af\u0631\u06cc\u06a9\u0627\u0646\u0633 \u0647\u0645\u0631\u0627\u0647 \u0627\u0633\u062a.", "\u0628\u0627 \u0622\u0646\u062f\u0631\u0648\u0698\u0646 \u0648 \u062a\u062e\u0645\u06a9\u200c\u06af\u0630\u0627\u0631\u06cc \u0637\u0628\u06cc\u0639\u06cc\u060c \u0647\u06cc\u0631\u0633\u0648\u062a\u06cc\u0633\u0645 \u0627\u06cc\u062f\u06cc\u0648\u067e\u0627\u062a\u06cc\u06a9 \u0645\u0637\u0631\u062d \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0647\u0627\u06cc\u067e\u0631\u067e\u0644\u0627\u0632\u06cc \u0622\u062f\u0631\u0646\u0627\u0644 \u0646\u0627\u06a9\u0644\u0627\u0633\u06cc\u06a9 \u0628\u0627 \u06f1\u06f7-\u0647\u06cc\u062f\u0631\u0648\u06a9\u0633\u06cc\u200c\u067e\u0631\u0648\u0698\u0633\u062a\u0631\u0648\u0646 \u0628\u0627\u0644\u0627 \u0648 \u067e\u0631\u0648\u0641\u0627\u06cc\u0644 \u063a\u06cc\u0631\u0637\u0628\u06cc\u0639\u06cc \u0647\u0645\u0631\u0627\u0647 \u0627\u0633\u062a."],
  },
  (28, 194): {
   "topic": "pregnancyVaccines",
   "lead": "\u0648\u0627\u06a9\u0633\u0646 \u0648\u0627\u0631\u06cc\u0633\u0644\u0627 (\u0632\u0646\u062f\u0647\u0654 \u062a\u0636\u0639\u06cc\u0641\u200c\u0634\u062f\u0647) \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0645\u0645\u0646\u0648\u0639 \u0627\u0633\u062a.",
   "interpretation": "\u0648\u0627\u06a9\u0633\u0646\u200c\u0647\u0627\u06cc \u0632\u0646\u062f\u0647\u0654 \u062a\u0636\u0639\u06cc\u0641\u200c\u0634\u062f\u0647 \u0645\u0627\u0646\u0646\u062f \u0648\u0627\u0631\u06cc\u0633\u0644\u0627\u060c \u0633\u0631\u062e\u062c\u0647 \u0648 \u0627\u0648\u0631\u06cc\u0648\u0646 (MMR) \u0648 \u062a\u0628 \u0632\u0631\u062f \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0628\u0647\u200c\u062e\u0627\u0637\u0631 \u062e\u0637\u0631 \u0646\u0638\u0631\u06cc \u0639\u0641\u0648\u0646\u062a \u062c\u0646\u06cc\u0646\u06cc \u0645\u0645\u0646\u0648\u0639\u200c\u0627\u0646\u062f \u0648 \u062f\u0631 \u0635\u0648\u0631\u062a \u0646\u06cc\u0627\u0632 \u067e\u06cc\u0634 \u0627\u0632 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u06cc\u0627 \u067e\u0633 \u0627\u0632 \u0632\u0627\u06cc\u0645\u0627\u0646 \u062a\u062c\u0648\u06cc\u0632 \u0645\u06cc\u200c\u0634\u0648\u0646\u062f\u061b \u062f\u0631 \u0645\u0642\u0627\u0628\u0644 \u0648\u0627\u06a9\u0633\u0646\u200c\u0647\u0627\u06cc \u063a\u06cc\u0631\u0632\u0646\u062f\u0647 \u0645\u0627\u0646\u0646\u062f \u0647\u067e\u0627\u062a\u06cc\u062a B\u060c \u0645\u0646\u0646\u06af\u0648\u06a9\u0648\u06a9 \u0648 \u0622\u0646\u0641\u0644\u0648\u0622\u0646\u0632\u0627\u06cc \u06a9\u0634\u062a\u0647\u200c\u0634\u062f\u0647 \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0645\u062c\u0627\u0632\u0646\u062f \u0648 \u0622\u0646\u0641\u0644\u0648\u0622\u0646\u0632\u0627 \u0628\u0647\u200c\u0637\u0648\u0631 \u0641\u0639\u0627\u0644 \u062a\u0648\u0635\u06cc\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f.",
   "reasons": ["\u0648\u0627\u06a9\u0633\u0646 \u0645\u0646\u0646\u06af\u0648\u06a9\u0648\u06a9 \u063a\u06cc\u0631\u0632\u0646\u062f\u0647 \u0627\u0633\u062a \u0648 \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0645\u0646\u0639 \u0646\u062f\u0627\u0631\u062f.", "\u0622\u0646\u0641\u0644\u0648\u0622\u0646\u0632\u0627\u06cc \u06a9\u0634\u062a\u0647\u200c\u0634\u062f\u0647 \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0627\u06cc\u0645\u0646 \u0648 \u062a\u0648\u0635\u06cc\u0647\u200c\u0634\u062f\u0647 \u0627\u0633\u062a.", "\u0648\u0627\u0631\u06cc\u0633\u0644\u0627 \u0648\u0627\u06a9\u0633\u0646 \u0632\u0646\u062f\u0647\u0654 \u062a\u0636\u0639\u06cc\u0641\u200c\u0634\u062f\u0647 \u0627\u0633\u062a \u0648 \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0645\u0645\u0646\u0648\u0639\u06cc\u062a \u062f\u0627\u0631\u062f\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0648\u0627\u06a9\u0633\u0646 \u0647\u067e\u0627\u062a\u06cc\u062a B \u063a\u06cc\u0631\u0632\u0646\u062f\u0647 \u0627\u0633\u062a \u0648 \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0645\u062c\u0627\u0632 \u0627\u0633\u062a."],
  },
  (28, 195): {
   "topic": "ascusReflexHpv",
   "lead": "\u067e\u0627\u067e \u0627\u0633\u0645\u06cc\u0631 ASC-US \u062f\u0631 \u0632\u0646 \u06f2\u06f5 \u0633\u0627\u0644\u0647: \u0622\u0632\u0645\u0627\u06cc\u0634 \u0628\u0627\u0632\u062a\u0627\u0628\u06cc HPV \u0628\u0647\u062a\u0631\u06cc\u0646 \u067e\u06cc\u06af\u06cc\u0631\u06cc \u0627\u0633\u062a.",
   "interpretation": "\u062f\u0631 \u0632\u0646 \u06f2\u06f5 \u0633\u0627\u0644\u0647 \u0648 \u0628\u0627\u0644\u0627\u062a\u0631 \u0628\u0627 \u0646\u062a\u06cc\u062c\u0647\u0654 ASC-US\u060c \u0627\u0646\u062c\u0627\u0645 \u0622\u0632\u0645\u0627\u06cc\u0634 HPV \u0631\u0648\u06cc \u0647\u0645\u0627\u0646 \u0646\u0645\u0648\u0646\u0647 (\u0631\u0648\u0634 \u0628\u0627\u0632\u062a\u0627\u0628\u06cc) \u06af\u0627\u0645 \u0646\u062e\u0633\u062a \u0627\u0633\u062a\u061b \u0627\u06af\u0631 HPV \u0645\u0646\u0641\u06cc \u0628\u0627\u0634\u062f \u062a\u06a9\u0631\u0627\u0631 \u067e\u0627\u067e \u062f\u0631 \u0641\u0648\u0627\u0635\u0644 \u0645\u0646\u0627\u0633\u0628 \u06a9\u0627\u0641\u06cc \u0627\u0633\u062a \u0648 \u0627\u06af\u0631 \u0645\u062b\u0628\u062a \u0628\u0627\u0634\u062f \u06a9\u0648\u0644\u067e\u0648\u0633\u06a9\u0648\u067e\u06cc \u0644\u0627\u0632\u0645 \u0645\u06cc\u200c\u0634\u0648\u062f. \u06a9\u0648\u0644\u067e\u0648\u0633\u06a9\u0648\u067e\u06cc \u0648 \u0628\u06cc\u0648\u067e\u0633\u06cc \u0628\u0631\u0627\u06cc \u0647\u0645\u0647\u0654 \u0645\u0648\u0627\u0631\u062f ASC-US \u0628\u06cc\u0634 \u0627\u0632 \u062d\u062f \u062a\u0647\u0627\u062c\u0645\u06cc \u0627\u0633\u062a\u060c \u062a\u06a9\u0631\u0627\u0631 \u067e\u0627\u067e \u0628\u062f\u0648\u0646 \u0633\u0646\u062c\u0634 HPV \u062f\u0642\u062a \u06a9\u0645\u200c\u062a\u0631\u06cc \u062f\u0627\u0631\u062f \u0648 \u0645\u062e\u0631\u0648\u0637\u200c\u0628\u0631\u062f\u0627\u0631\u06cc \u062f\u0631 \u0627\u06cc\u0646 \u0645\u0631\u062d\u0644\u0647 \u062c\u0627\u06cc\u06af\u0627\u0647\u06cc \u0646\u062f\u0627\u0631\u062f.",
   "reasons": ["\u0622\u0632\u0645\u0627\u06cc\u0634 \u0628\u0627\u0632\u062a\u0627\u0628\u06cc HPV \u0631\u0648\u06cc \u0647\u0645\u0627\u0646 \u0646\u0645\u0648\u0646\u0647\u060c \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u067e\u06cc\u06af\u06cc\u0631\u06cc ASC-US \u062f\u0631 \u0627\u06cc\u0646 \u0633\u0646 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u06a9\u0648\u0644\u067e\u0648\u0633\u06a9\u0648\u067e\u06cc \u0648 \u0628\u06cc\u0648\u067e\u0633\u06cc \u0628\u0631\u0627\u06cc \u0647\u0645\u0647\u0654 \u0645\u0648\u0627\u0631\u062f ASC-US \u0628\u06cc\u0634 \u0627\u0632 \u062d\u062f \u062a\u0647\u0627\u062c\u0645\u06cc \u0627\u0633\u062a.", "\u062a\u06a9\u0631\u0627\u0631 \u067e\u0627\u067e \u0627\u0633\u0645\u06cc\u0631 \u0628\u062f\u0648\u0646 \u0633\u0646\u062c\u0634 HPV \u062f\u0642\u062a \u06a9\u0645\u200c\u062a\u0631\u06cc \u0627\u0632 \u0631\u0648\u0634 \u0628\u0627\u0632\u062a\u0627\u0628\u06cc \u062f\u0627\u0631\u062f.", "\u0645\u062e\u0631\u0648\u0637\u200c\u0628\u0631\u062f\u0627\u0631\u06cc \u0648 \u0646\u0645\u0648\u0646\u0647\u200c\u0628\u0631\u062f\u0627\u0631\u06cc \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u062f\u0631 ASC-US \u0642\u062f\u0645 \u0627\u0648\u0644 \u0646\u06cc\u0633\u062a."],
  },
  (28, 196): {
   "topic": "iugrDuctusVenosusDeliver",
   "lead": "\u0645\u062d\u062f\u0648\u062f\u06cc\u062a \u0631\u0634\u062f \u062c\u0646\u06cc\u0646 \u062f\u0631 \u06f3\u06f6 \u0647\u0641\u062a\u0647 \u0628\u0627 \u062a\u063a\u06cc\u06cc\u0631\u0627\u062a \u0645\u062c\u0631\u0627\u06cc \u0648\u0631\u06cc\u062f\u06cc (ductus venosus): \u062e\u062a\u0645 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc.",
   "interpretation": "\u062f\u0631 \u0645\u062d\u062f\u0648\u062f\u06cc\u062a \u0631\u0634\u062f \u062c\u0646\u06cc\u0646\u060c \u062a\u063a\u06cc\u06cc\u0631\u0627\u062a \u062c\u0631\u06cc\u0627\u0646 \u0645\u062c\u0631\u0627\u06cc \u0648\u0631\u06cc\u062f\u06cc (\u0628\u0631\u06af\u0634\u062a \u062c\u0631\u06cc\u0627\u0646 \u062f\u0631 \u0645\u0648\u062c \u062f\u0647\u0644\u06cc\u0632\u06cc) \u0646\u0634\u0627\u0646\u0647\u0654 \u0627\u0633\u06cc\u062f\u0645\u06cc \u0648 \u0646\u0627\u0631\u0633\u0627\u06cc\u06cc \u0642\u0644\u0628\u06cc \u062c\u0646\u06cc\u0646 \u0627\u0633\u062a \u0648 \u062f\u0631 \u06f3\u06f6 \u0647\u0641\u062a\u0647 \u06a9\u0647 \u0628\u0642\u0627\u06cc \u062e\u0627\u0631\u062c \u0631\u062d\u0645\u06cc \u0645\u0637\u0644\u0648\u0628 \u0627\u0633\u062a\u060c \u062e\u062a\u0645 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0631\u0627 \u0636\u0631\u0648\u0631\u06cc \u0645\u06cc\u200c\u06a9\u0646\u062f. \u0628\u06cc\u0648\u0641\u06cc\u0632\u06cc\u06a9\u0627\u0644 \u067e\u0631\u0648\u0641\u0627\u06cc\u0644 \u0648 \u062a\u06a9\u0631\u0627\u0631 \u062f\u0627\u067e\u0644\u0631 \u06cc\u06a9 \u0647\u0641\u062a\u0647 \u0628\u0639\u062f\u060c \u0645\u062f\u06cc\u0631\u06cc\u062a \u0627\u0646\u062a\u0638\u0627\u0631\u06cc \u0646\u0627\u06a9\u0627\u0641\u06cc \u062f\u0631 \u0646\u0627\u0631\u0633\u0627\u06cc\u06cc \u0642\u0644\u0628 \u062c\u0646\u06cc\u0646 \u0627\u0633\u062a \u0648 \u0627\u062f\u0627\u0645\u0647\u0654 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062a\u0627 \u062a\u0631\u0645 \u062e\u0637\u0631 \u0645\u0631\u06af \u062c\u0646\u06cc\u0646 \u0631\u0627 \u0628\u0627\u0644\u0627 \u0645\u06cc\u200c\u0628\u0631\u062f.",
   "reasons": ["\u0628\u06cc\u0648\u0641\u06cc\u0632\u06cc\u06a9\u0627\u0644 \u067e\u0631\u0648\u0641\u0627\u06cc\u0644 \u062f\u0631 \u062d\u0636\u0648\u0631 \u062a\u063a\u06cc\u06cc\u0631\u0627\u062a \u0645\u062c\u0631\u0627\u06cc \u0648\u0631\u06cc\u062f\u06cc\u060c \u0645\u062f\u06cc\u0631\u06cc\u062a \u0627\u0646\u062a\u0638\u0627\u0631\u06cc \u06a9\u0627\u0641\u06cc \u0646\u06cc\u0633\u062a.", "\u062a\u06a9\u0631\u0627\u0631 \u062f\u0627\u067e\u0644\u0631 \u06cc\u06a9 \u0647\u0641\u062a\u0647 \u0628\u0639\u062f \u062a\u0623\u062e\u06cc\u0631\u06cc \u062e\u0637\u0631\u0646\u0627\u06a9 \u062f\u0631 \u0646\u0627\u0631\u0633\u0627\u06cc\u06cc \u0642\u0644\u0628 \u062c\u0646\u06cc\u0646 \u0627\u0633\u062a.", "\u0627\u062f\u0627\u0645\u0647\u0654 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062a\u0627 \u062a\u0631\u0645 \u0628\u0627 \u0646\u0627\u0631\u0633\u0627\u06cc\u06cc \u0645\u062c\u0631\u0627\u06cc \u0648\u0631\u06cc\u062f\u06cc \u062e\u0637\u0631 \u0645\u0631\u06af \u062c\u0646\u06cc\u0646 \u062f\u0627\u0631\u062f.", "\u062a\u063a\u06cc\u06cc\u0631\u0627\u062a \u0645\u062c\u0631\u0627\u06cc \u0648\u0631\u06cc\u062f\u06cc \u062f\u0631 \u06f3\u06f6 \u0647\u0641\u062a\u0647 \u0627\u0646\u062f\u06cc\u06a9\u0627\u0633\u06cc\u0648\u0646 \u062e\u062a\u0645 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d."],
  },
  (28, 197): {
   "topic": "infertilitySemenFirst",
   "lead": "\u0627\u0648\u0644\u06cc\u0646 \u0628\u0631\u0631\u0633\u06cc \u0636\u0631\u0648\u0631\u06cc \u062f\u0631 \u06a9\u0627\u0631\u0622\u067e \u0632\u0648\u062c \u0646\u0627\u0628\u0627\u0631\u0648\u0631: \u0622\u0646\u0627\u0644\u06cc\u0632 \u0627\u0633\u067e\u0631\u0645 \u0645\u0631\u062f \u0627\u0633\u062a.",
   "interpretation": "\u0622\u0646\u0627\u0644\u06cc\u0632 \u0627\u0633\u067e\u0631\u0645 \u0633\u0627\u062f\u0647\u060c \u06a9\u0645\u200c\u0647\u0632\u06cc\u0646\u0647 \u0648 \u063a\u06cc\u0631\u062a\u0647\u0627\u062c\u0645\u06cc \u0627\u0633\u062a \u0648 \u0628\u062e\u0634 \u0642\u0627\u0628\u0644\u200c\u062a\u0648\u062c\u0647\u06cc \u0627\u0632 \u0646\u0627\u0628\u0627\u0631\u0648\u0631\u06cc\u200c\u0647\u0627 \u0639\u0644\u062a \u0645\u0631\u062f\u0627\u0646\u0647 \u062f\u0627\u0631\u062f\u061b \u0628\u0646\u0627\u0628\u0631\u0627\u06cc\u0646 \u062f\u0631 \u06af\u0627\u0645 \u0646\u062e\u0633\u062a \u0648 \u0647\u0645\u0632\u0645\u0627\u0646 \u0628\u0627 \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u0632\u0646 \u0627\u0646\u062c\u0627\u0645 \u0645\u06cc\u200c\u0634\u0648\u062f. \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u0648 \u0628\u06cc\u0648\u067e\u0633\u06cc \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u0648 \u0644\u0627\u067e\u0627\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u062f\u0631 \u067e\u0644\u0647\u200c\u0647\u0627\u06cc \u0628\u0639\u062f\u06cc \u0648 \u0641\u0642\u0637 \u0628\u0627 \u0627\u0646\u062f\u06cc\u06a9\u0627\u0633\u06cc\u0648\u0646 \u0645\u0637\u0631\u062d \u0645\u06cc\u200c\u0634\u0648\u0646\u062f.",
   "reasons": ["\u0622\u0646\u0627\u0644\u06cc\u0632 \u0627\u0633\u067e\u0631\u0645 \u0627\u0648\u0644\u06cc\u0646 \u0628\u0631\u0631\u0633\u06cc \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u0648 \u06a9\u0645\u200c\u0647\u0632\u06cc\u0646\u0647 \u06a9\u0627\u0631\u0622\u067e \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u067e\u0633 \u0627\u0632 \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc\u200c\u0647\u0627\u06cc \u067e\u0627\u06cc\u0647 \u0648 \u062f\u0631 \u0635\u0648\u0631\u062a \u0646\u06cc\u0627\u0632 \u0627\u0646\u062c\u0627\u0645 \u0645\u06cc\u200c\u0634\u0648\u062f.", "\u0628\u06cc\u0648\u067e\u0633\u06cc \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u062f\u0631 \u0628\u0631\u0631\u0633\u06cc \u0631\u0648\u062a\u06cc\u0646 \u0646\u0627\u0632\u0627\u06cc\u06cc \u0627\u0646\u062c\u0627\u0645 \u0646\u0645\u06cc\u200c\u0634\u0648\u062f \u0648 \u0627\u0646\u062f\u06cc\u06a9\u0627\u0633\u06cc\u0648\u0646 \u062e\u0627\u0635 \u062f\u0627\u0631\u062f.", "\u0644\u0627\u067e\u0627\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u067e\u0644\u0647\u0654 \u067e\u0627\u06cc\u0627\u0646\u06cc \u0628\u0631\u0631\u0633\u06cc \u0646\u0627\u0632\u0627\u06cc\u06cc \u0627\u0633\u062a \u0646\u0647 \u0628\u0631\u0631\u0633\u06cc \u0627\u0648\u0644\u06cc\u0647."],
  },
  (28, 198): {
   "topic": "postdatesInduceFavourable",
   "lead": "\u06f4\u06f1 \u0647\u0641\u062a\u0647 \u0648 \u062f\u0648 \u0631\u0648\u0632 \u0628\u0627 \u0633\u0631\u0648\u06cc\u06a9\u0633 \u0645\u0637\u0644\u0648\u0628 (\u0627\u0641\u0627\u0633\u0645\u0627\u0646 \u06f8\u06f0\u066a \u0648 \u062f\u0647\u0627\u0646\u0647\u0654 \u06f2-\u06f3 \u0633\u0627\u0646\u062a\u06cc\u200c\u0645\u062a\u0631): \u0627\u0644\u0642\u0627\u06cc \u0632\u0627\u06cc\u0645\u0627\u0646.",
   "interpretation": "\u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u067e\u0633 \u0627\u0632 \u062a\u0631\u0645 \u0628\u0627 \u0633\u0631\u0648\u06cc\u06a9\u0633 \u0646\u0631\u0645 \u0648 \u0642\u062f\u0627\u0645\u06cc \u0648 \u0627\u0641\u0627\u0633\u0645\u0627\u0646 \u0628\u0627\u0644\u0627\u06cc \u06f8\u06f0\u066a\u060c \u0627\u0644\u0642\u0627\u06cc \u0632\u0627\u06cc\u0645\u0627\u0646 \u0645\u0648\u0641\u0642\u06cc\u062a \u0628\u0627\u0644\u0627\u06cc\u06cc \u062f\u0627\u0631\u062f \u0648 \u0627\u062f\u0627\u0645\u0647\u0654 \u0627\u0646\u062a\u0638\u0627\u0631 \u062e\u0637\u0631 \u0645\u06a9\u0648\u0646\u06cc\u0648\u0645 \u0648 \u0627\u0641\u062a \u0636\u0631\u0628\u0627\u0646 \u062c\u0646\u06cc\u0646 \u0631\u0627 \u0628\u0627\u0644\u0627 \u0645\u06cc\u200c\u0628\u0631\u062f\u061b \u0633\u0632\u0627\u0631\u06cc\u0646 \u0627\u0648\u0631\u0698\u0627\u0646\u0633 \u062f\u0631 \u0646\u0628\u0648\u062f \u0627\u0646\u062f\u06cc\u06a9\u0627\u0633\u06cc\u0648\u0646 \u0641\u0648\u0631\u06cc \u0627\u0646\u062c\u0627\u0645 \u0646\u0645\u06cc\u200c\u0634\u0648\u062f\u060c \u067e\u0627\u06cc\u0634 \u062f\u0648 \u0628\u0627\u0631 \u062f\u0631 \u0647\u0641\u062a\u0647 \u0628\u0631\u0646\u0627\u0645\u0647\u0654 \u0627\u0646\u062a\u0638\u0627\u0631\u06cc \u0627\u0633\u062a \u0646\u0647 \u0627\u0642\u062f\u0627\u0645 \u062f\u0631\u0645\u0627\u0646\u06cc \u0648 \u0628\u06cc\u0648\u0641\u06cc\u0632\u06cc\u06a9\u0627\u0644 \u067e\u0631\u0648\u0641\u0627\u06cc\u0644 \u062a\u0646\u0647\u0627 \u0648\u0636\u0639\u06cc\u062a \u062c\u0646\u06cc\u0646 \u0631\u0627 \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u0645\u06cc\u200c\u06a9\u0646\u062f.",
   "reasons": ["\u0633\u0632\u0627\u0631\u06cc\u0646 \u0627\u0648\u0631\u0698\u0627\u0646\u0633 \u062f\u0631 \u0646\u0628\u0648\u062f \u0627\u0646\u062f\u06cc\u06a9\u0627\u0633\u06cc\u0648\u0646 \u0641\u0648\u0631\u06cc \u0645\u0627\u062f\u0631 \u06cc\u0627 \u062c\u0646\u06cc\u0646 \u0644\u0627\u0632\u0645 \u0646\u06cc\u0633\u062a.", "\u067e\u0627\u06cc\u0634 \u062f\u0648 \u0628\u0627\u0631 \u062f\u0631 \u0647\u0641\u062a\u0647 \u062f\u0631 \u06f4\u06f1 \u0647\u0641\u062a\u0647 \u0628\u0627 \u0633\u0631\u0648\u06cc\u06a9\u0633 \u0645\u0637\u0644\u0648\u0628 \u06a9\u0627\u0641\u06cc \u0646\u06cc\u0633\u062a.", "\u0628\u06cc\u0648\u0641\u06cc\u0632\u06cc\u06a9\u0627\u0644 \u067e\u0631\u0648\u0641\u0627\u06cc\u0644 \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u0648\u0636\u0639\u06cc\u062a \u0627\u0633\u062a \u0648 \u0627\u0642\u062f\u0627\u0645 \u062f\u0631\u0645\u0627\u0646\u06cc \u0645\u062d\u0633\u0648\u0628 \u0646\u0645\u06cc\u200c\u0634\u0648\u062f.", "\u062f\u0631 \u067e\u0633 \u0627\u0632 \u062a\u0631\u0645 \u0628\u0627 \u0633\u0631\u0648\u06cc\u06a9\u0633 \u0645\u0637\u0644\u0648\u0628\u060c \u0627\u0644\u0642\u0627\u06cc \u0632\u0627\u06cc\u0645\u0627\u0646 \u0628\u0647\u062a\u0631\u06cc\u0646 \u0627\u0642\u062f\u0627\u0645 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d."],
  },
  (28, 199): {
   "topic": "postmenoAdnexalMassOncologyRefer",
   "lead": "\u062a\u0648\u062f\u0647\u0654 \u062a\u0648\u067e\u064f\u0631 \u062a\u062e\u0645\u062f\u0627\u0646 \u06f8 \u0633\u0627\u0646\u062a\u06cc\u200c\u0645\u062a\u0631\u06cc \u0628\u0627 CA125 \u0628\u0631\u0627\u0628\u0631 \u06f4\u06f0\u06f0 \u062f\u0631 \u06f6\u06f0 \u0633\u0627\u0644\u06af\u06cc: \u0627\u0631\u062c\u0627\u0639 \u0628\u0647 \u0627\u0646\u06a9\u0648\u0644\u0648\u0698\u06cc\u0633\u062a \u0632\u0646\u0627\u0646.",
   "interpretation": "\u062a\u0648\u062f\u0647\u0654 \u062a\u0648\u067e\u064f\u0631 (Solid) \u062a\u062e\u0645\u062f\u0627\u0646 \u062f\u0631 \u0633\u0646 \u067e\u0633 \u0627\u0632 \u06cc\u0627\u0626\u0633\u06af\u06cc \u0647\u0645\u0631\u0627\u0647 \u0628\u0627 CA125 \u0628\u0627\u0644\u0627\u060c \u0628\u062f\u062e\u06cc\u0645\u06cc \u0631\u0627 \u0628\u0633\u06cc\u0627\u0631 \u0645\u062d\u062a\u0645\u0644 \u0645\u06cc\u200c\u06a9\u0646\u062f \u0648 \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u062f\u0631\u0645\u0627\u0646\u060c \u0627\u0631\u062c\u0627\u0639 \u0628\u0647 \u0627\u0646\u06a9\u0648\u0644\u0648\u0698\u06cc\u0633\u062a \u0632\u0646\u0627\u0646 \u0628\u0631\u0627\u06cc \u062c\u0631\u0627\u062d\u06cc \u0645\u0646\u0627\u0633\u0628 \u0648 \u0645\u0631\u062d\u0644\u0647\u200c\u0628\u0646\u062f\u06cc \u0627\u0633\u062a\u061b \u062a\u062d\u062a \u0646\u0638\u0631 \u06af\u0631\u0641\u062a\u0646 \u062a\u0648\u062f\u0647\u0654 \u062a\u0648\u067e\u064f\u0631 \u062f\u0631 \u0627\u06cc\u0646 \u0633\u0646 \u062e\u0637\u0631\u0646\u0627\u06a9 \u0627\u0633\u062a \u0648 \u0633\u06cc\u0633\u062a\u06a9\u062a\u0648\u0645\u06cc \u06cc\u0627 \u0647\u06cc\u0633\u062a\u0631\u06a9\u062a\u0648\u0645\u06cc \u0628\u062f\u0648\u0646 \u0645\u0631\u062d\u0644\u0647\u200c\u0628\u0646\u062f\u06cc \u0648 \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u0627\u0646\u06a9\u0648\u0644\u0648\u0698\u06cc\u06a9\u060c \u062f\u0631\u0645\u0627\u0646 \u0646\u0627\u06a9\u0627\u0641\u06cc \u0645\u062d\u0633\u0648\u0628 \u0645\u06cc\u200c\u0634\u0648\u062f.",
   "reasons": ["\u062a\u062d\u062a \u0646\u0638\u0631 \u06af\u0631\u0641\u062a\u0646 \u062a\u0648\u062f\u0647\u0654 \u062a\u0648\u067e\u064f\u0631 \u0628\u0627 CA125 \u0628\u0627\u0644\u0627 \u062f\u0631 \u0633\u0646 \u067e\u0633 \u0627\u0632 \u06cc\u0627\u0626\u0633\u06af\u06cc \u062e\u0637\u0631\u0646\u0627\u06a9 \u0627\u0633\u062a.", "\u0633\u06cc\u0633\u062a\u06a9\u062a\u0648\u0645\u06cc \u0628\u0647\u200c\u062a\u0646\u0647\u0627\u06cc\u06cc \u0628\u0631\u0627\u06cc \u0628\u062f\u062e\u06cc\u0645\u06cc \u0627\u062d\u062a\u0645\u0627\u0644\u06cc \u062f\u0631\u0645\u0627\u0646 \u06a9\u0627\u0641\u06cc \u0646\u06cc\u0633\u062a.", "\u0647\u06cc\u0633\u062a\u0631\u06a9\u062a\u0648\u0645\u06cc \u0628\u062f\u0648\u0646 \u0645\u0631\u062d\u0644\u0647\u200c\u0628\u0646\u062f\u06cc \u0648 \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u0627\u0646\u06a9\u0648\u0644\u0648\u0698\u06cc\u06a9 \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u062f\u0631\u0645\u0627\u0646 \u0646\u06cc\u0633\u062a.", "\u0627\u0631\u062c\u0627\u0639 \u0628\u0647 \u0627\u0646\u06a9\u0648\u0644\u0648\u0698\u06cc\u0633\u062a \u0632\u0646\u0627\u0646 \u0628\u0631\u0627\u06cc \u062c\u0631\u0627\u062d\u06cc \u0648 \u0645\u0631\u062d\u0644\u0647\u200c\u0628\u0646\u062f\u06cc \u0644\u0627\u0632\u0645 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d."],
  },
  (28, 200): {
   "topic": "turnerMosaicGonadectomy",
   "lead": "\u0622\u0645\u0646\u0648\u0631\u0647\u0654 \u0627\u0648\u0644\u06cc\u0647 \u0628\u0627 \u06a9\u0627\u0631\u06cc\u0648\u062a\u0627\u06cc\u067e \u06f4\u06f5X/\u06f4\u06f6XY \u0648 \u062a\u0648\u062f\u0647\u0654 \u062a\u062e\u0645\u062f\u0627\u0646\u06cc: \u06af\u0646\u0627\u062f\u06a9\u062a\u0648\u0645\u06cc \u062f\u0648\u0637\u0631\u0641\u0647.",
   "interpretation": "\u0648\u062c\u0648\u062f \u0645\u0627\u062f\u0647\u0654 Y \u062f\u0631 \u06a9\u0627\u0631\u06cc\u0648\u062a\u0627\u06cc\u067e \u0645\u0648\u0632\u0627\u0626\u06cc\u06a9 \u062a\u0631\u0646\u0631\u060c \u062e\u0637\u0631 \u062a\u0648\u0645\u0648\u0631\u0647\u0627\u06cc \u06af\u0646\u0627\u062f\u06cc \u0645\u0627\u0646\u0646\u062f \u06af\u0646\u0627\u062f\u0648\u0628\u0644\u0627\u0633\u062a\u0648\u0645\u0627 \u0648 \u062f\u06cc\u0633\u200c\u0698\u0631\u0645\u06cc\u0646\u0648\u0645\u0627 \u0631\u0627 \u0628\u0647\u200c\u0637\u0648\u0631 \u0686\u0634\u0645\u06af\u06cc\u0631 \u0628\u0627\u0644\u0627 \u0645\u06cc\u200c\u0628\u0631\u062f \u0648 \u0628\u0631\u062f\u0627\u0634\u062a\u0646 \u0647\u0631 \u062f\u0648 \u06af\u0646\u0627\u062f \u0644\u0627\u0632\u0645 \u0627\u0633\u062a. \u0628\u0631\u062f\u0627\u0634\u062a\u0646 \u06af\u0646\u0627\u062f \u06cc\u06a9 \u0637\u0631\u0641\u060c \u06af\u0646\u0627\u062f \u0628\u0627\u0642\u06cc\u200c\u0645\u0627\u0646\u062f\u0647 \u067e\u0631\u062e\u0637\u0631 \u0631\u0627 \u0631\u0647\u0627 \u0645\u06cc\u200c\u06a9\u0646\u062f\u060c \u0647\u06cc\u0633\u062a\u0631\u06a9\u062a\u0648\u0645\u06cc \u0628\u062f\u0648\u0646 \u0627\u0646\u062f\u06cc\u06a9\u0627\u0633\u06cc\u0648\u0646 \u0631\u062d\u0645\u06cc \u0627\u0646\u062c\u0627\u0645 \u0646\u0645\u06cc\u200c\u0634\u0648\u062f \u0648 \u0634\u06cc\u0645\u06cc\u200c\u062f\u0631\u0645\u0627\u0646\u06cc \u062f\u0631 \u0646\u0628\u0648\u062f \u0628\u062f\u062e\u06cc\u0645\u06cc \u06af\u0633\u062a\u0631\u062f\u0647\u0654 \u062a\u0623\u06cc\u06cc\u062f\u0634\u062f\u0647\u060c \u0627\u0642\u062f\u0627\u0645 \u0627\u0648\u0644\u06cc\u0647 \u0646\u06cc\u0633\u062a.",
   "reasons": ["\u0628\u0631\u062f\u0627\u0634\u062a\u0646 \u06cc\u06a9 \u06af\u0646\u0627\u062f\u060c \u062e\u0637\u0631 \u06af\u0646\u0627\u062f \u0628\u0627\u0642\u06cc\u200c\u0645\u0627\u0646\u062f\u0647 \u0631\u0627 \u0628\u0631\u0637\u0631\u0641 \u0646\u0645\u06cc\u200c\u06a9\u0646\u062f.", "\u0647\u06cc\u0633\u062a\u0631\u06a9\u062a\u0648\u0645\u06cc \u062f\u0631 \u0627\u06cc\u0646 \u0628\u06cc\u0645\u0627\u0631 \u0628\u062f\u0648\u0646 \u0627\u0646\u062f\u06cc\u06a9\u0627\u0633\u06cc\u0648\u0646 \u0631\u062d\u0645\u06cc \u0627\u0646\u062c\u0627\u0645 \u0646\u0645\u06cc\u200c\u0634\u0648\u062f.", "\u0634\u06cc\u0645\u06cc\u200c\u062f\u0631\u0645\u0627\u0646\u06cc \u062f\u0631 \u0646\u0628\u0648\u062f \u0628\u062f\u062e\u06cc\u0645\u06cc \u062a\u0623\u06cc\u06cc\u062f\u0634\u062f\u0647\u060c \u0627\u0642\u062f\u0627\u0645 \u0627\u0648\u0644\u06cc\u0647 \u0646\u06cc\u0633\u062a.", "\u0628\u0627 \u0648\u062c\u0648\u062f \u0645\u0627\u062f\u0647\u0654 Y \u062f\u0631 \u06a9\u0627\u0631\u06cc\u0648\u062a\u0627\u06cc\u067e\u060c \u06af\u0646\u0627\u062f\u06a9\u062a\u0648\u0645\u06cc \u062f\u0648\u0637\u0631\u0641\u0647 \u0636\u0631\u0648\u0631\u06cc \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d."],
  },
  (28, 201): {
   "topic": "ntdHighDoseFolicAcid",
   "lead": "\u0628\u0627 \u0633\u0627\u0628\u0642\u0647\u0654 \u0646\u0648\u0632\u0627\u062f \u0645\u0628\u062a\u0644\u0627 \u0628\u0647 \u0622\u0646\u0627\u0646\u0633\u0641\u0627\u0644\u06cc: \u0627\u0633\u06cc\u062f \u0641\u0648\u0644\u06cc\u06a9 \u06f4 \u0645\u06cc\u0644\u06cc\u200c\u06af\u0631\u0645 \u0631\u0648\u0632\u0627\u0646\u0647 \u062a\u0648\u0635\u06cc\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f.",
   "interpretation": "\u062f\u0631 \u0632\u0646\u0627\u0646\u06cc \u06a9\u0647 \u067e\u06cc\u0634\u200c\u062a\u0631 \u062c\u0646\u06cc\u0646 \u06cc\u0627 \u0646\u0648\u0632\u0627\u062f \u0628\u0627 \u0646\u0642\u0635 \u0644\u0648\u0644\u0647\u0654 \u0639\u0635\u0628\u06cc \u062f\u0627\u0634\u062a\u0647\u200c\u0627\u0646\u062f\u060c \u062f\u0648\u0632 \u0628\u0627\u0644\u0627\u06cc \u0627\u0633\u06cc\u062f \u0641\u0648\u0644\u06cc\u06a9 (\u06f4 \u0645\u06cc\u0644\u06cc\u200c\u06af\u0631\u0645 \u0631\u0648\u0632\u0627\u0646\u0647) \u0627\u0632 \u062d\u062f\u0648\u062f \u06cc\u06a9 \u0645\u0627\u0647 \u067e\u06cc\u0634 \u0627\u0632 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062a\u0627 \u067e\u0627\u06cc\u0627\u0646 \u0633\u0647\u200c\u0645\u0627\u0647\u0647\u0654 \u0627\u0648\u0644 \u062a\u0648\u0635\u06cc\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f. \u062f\u0648\u0632\u0647\u0627\u06cc \u06f0\u066b\u06f4 \u0648 \u06f0\u066b\u06f8 \u0648 \u06f1 \u0645\u06cc\u0644\u06cc\u200c\u06af\u0631\u0645 \u0628\u0631\u0627\u06cc \u067e\u06cc\u0634\u06af\u06cc\u0631\u06cc \u062f\u0631 \u0632\u0646\u0627\u0646 \u06a9\u0645\u200c\u062e\u0637\u0631 \u06cc\u0627 \u0628\u0627 \u062e\u0637\u0631 \u0645\u062a\u0648\u0633\u0637 \u06a9\u0627\u0631\u0628\u0631\u062f \u062f\u0627\u0631\u0646\u062f \u0648 \u062f\u0631 \u0627\u06cc\u0646 \u06af\u0631\u0648\u0647 \u067e\u0631\u062e\u0637\u0631 \u0627\u062b\u0631 \u0645\u062d\u0627\u0641\u0638\u062a\u06cc \u06a9\u0627\u0641\u06cc \u0646\u062f\u0627\u0631\u0646\u062f.",
   "reasons": ["\u06f0\u066b\u06f4 \u0645\u06cc\u0644\u06cc\u200c\u06af\u0631\u0645 \u062f\u0648\u0632 \u0631\u0648\u062a\u06cc\u0646 \u0632\u0646\u0627\u0646 \u06a9\u0645\u200c\u062e\u0637\u0631 \u0627\u0633\u062a\u060c \u0646\u0647 \u06af\u0631\u0648\u0647 \u067e\u0631\u062e\u0637\u0631.", "\u06f0\u066b\u06f8 \u0645\u06cc\u0644\u06cc\u200c\u06af\u0631\u0645 \u0628\u0631\u0627\u06cc \u0627\u06cc\u0646 \u0633\u0637\u062d \u0627\u0632 \u062e\u0637\u0631 \u06a9\u0627\u0641\u06cc \u0646\u06cc\u0633\u062a.", "\u06f1 \u0645\u06cc\u0644\u06cc\u200c\u06af\u0631\u0645 \u062f\u0648\u0632 \u067e\u06cc\u0634\u06af\u06cc\u0631\u06cc \u06af\u0631\u0648\u0647\u200c\u0647\u0627\u06cc \u0628\u0627 \u062e\u0637\u0631 \u0645\u062a\u0648\u0633\u0637 \u0627\u0633\u062a \u0646\u0647 \u067e\u0631\u062e\u0637\u0631.", "\u06f4 \u0645\u06cc\u0644\u06cc\u200c\u06af\u0631\u0645 \u0631\u0648\u0632\u0627\u0646\u0647 \u0628\u0631\u0627\u06cc \u0633\u0627\u0628\u0642\u0647\u0654 \u0646\u0642\u0635 \u0644\u0648\u0644\u0647\u0654 \u0639\u0635\u0628\u06cc \u062a\u0648\u0635\u06cc\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d."],
  },
  (28, 202): {
   "topic": "abruptioDiagnosis",
   "lead": "\u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u0648\u0627\u0698\u06cc\u0646\u0627\u0644\u060c \u062f\u0631\u062f\u060c \u0627\u0646\u0642\u0628\u0627\u0636\u0627\u062a \u062a\u062a\u0627\u0646\u06cc\u06a9 \u0631\u062d\u0645 \u0648 \u0627\u0644\u06af\u0648\u06cc \u0633\u06cc\u0646\u0648\u0632\u0648\u0626\u06cc\u062f\u06cc \u0636\u0631\u0628\u0627\u0646 \u062c\u0646\u06cc\u0646: \u062f\u06a9\u0648\u0644\u0645\u0627\u0646 \u062c\u0641\u062a.",
   "interpretation": "\u062f\u06a9\u0648\u0644\u0645\u0627\u0646 \u062c\u0641\u062a \u0628\u0627 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u0648\u0627\u0698\u06cc\u0646\u0627\u0644\u060c \u062f\u0631\u062f \u0634\u06a9\u0645\u06cc\u060c \u0631\u062d\u0645 \u062d\u0633\u0627\u0633 \u0648 \u0647\u0627\u06cc\u067e\u0631\u062a\u0648\u0646\u06cc\u06a9 (\u0627\u0646\u0642\u0628\u0627\u0636\u0627\u062a \u062a\u062a\u0627\u0646\u06cc\u06a9) \u0648 \u0627\u0644\u06af\u0648\u06cc \u0633\u06cc\u0646\u0648\u0632\u0648\u0626\u06cc\u062f\u06cc \u06cc\u0627 \u0627\u0641\u062a \u0636\u0631\u0628\u0627\u0646 \u062c\u0646\u06cc\u0646 \u0628\u0647\u200c\u0639\u0644\u062a \u0647\u06cc\u067e\u0648\u06a9\u0633\u06cc \u0638\u0627\u0647\u0631 \u0645\u06cc\u200c\u0634\u0648\u062f. \u062c\u0641\u062a \u0633\u0631\u0631\u0627\u0647\u06cc \u0645\u0639\u0645\u0648\u0644\u0627\u064b \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u0628\u06cc\u200c\u062f\u0631\u062f \u0645\u06cc\u200c\u062f\u0647\u062f\u060c \u0648\u0627\u0632\u0627\u067e\u0631\u0648\u06cc\u0627 \u0631\u062d\u0645 \u0647\u0627\u06cc\u067e\u0631\u062a\u0648\u0646\u06cc\u06a9 \u0648 \u0627\u0646\u0642\u0628\u0627\u0636\u0627\u062a \u062a\u062a\u0627\u0646\u06cc\u06a9 \u0646\u0645\u06cc\u200c\u0633\u0627\u0632\u062f \u0648 \u062c\u0641\u062a \u0622\u06a9\u0631\u06cc\u062a\u0627 \u0645\u0639\u0645\u0648\u0644\u0627\u064b \u062d\u06cc\u0646 \u0632\u0627\u06cc\u0645\u0627\u0646 \u0648 \u0628\u0627 \u0645\u0634\u06a9\u0644 \u062c\u062f\u0627 \u0634\u062f\u0646 \u062c\u0641\u062a \u0634\u0646\u0627\u062e\u062a\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f.",
   "reasons": ["\u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u062f\u0631\u062f\u0646\u0627\u06a9 \u0647\u0645\u0631\u0627\u0647 \u0631\u062d\u0645 \u0647\u0627\u06cc\u067e\u0631\u062a\u0648\u0646\u06cc\u06a9 \u0648 \u0627\u0644\u06af\u0648\u06cc \u0633\u06cc\u0646\u0648\u0632\u0648\u0626\u06cc\u062f\u06cc\u060c \u062f\u06a9\u0648\u0644\u0645\u0627\u0646 \u062c\u0641\u062a \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u062c\u0641\u062a \u0633\u0631\u0631\u0627\u0647\u06cc \u0645\u0639\u0645\u0648\u0644\u0627\u064b \u0628\u0627 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u0628\u06cc\u200c\u062f\u0631\u062f \u0648 \u0631\u062d\u0645 \u063a\u06cc\u0631\u062d\u0633\u0627\u0633 \u0647\u0645\u0631\u0627\u0647 \u0627\u0633\u062a.", "\u0648\u0627\u0632\u0627\u067e\u0631\u0648\u06cc\u0627 \u0631\u062d\u0645 \u0647\u0627\u06cc\u067e\u0631\u062a\u0648\u0646\u06cc\u06a9 \u0648 \u0627\u0646\u0642\u0628\u0627\u0636\u0627\u062a \u062a\u062a\u0627\u0646\u06cc\u06a9 \u0646\u0645\u06cc\u200c\u0633\u0627\u0632\u062f.", "\u062c\u0641\u062a \u0622\u06a9\u0631\u06cc\u062a\u0627 \u0628\u0627 \u0686\u0633\u0628\u0646\u062f\u06af\u06cc \u0648 \u0645\u0634\u06a9\u0644 \u062c\u062f\u0627 \u0634\u062f\u0646 \u062c\u0641\u062a \u062d\u06cc\u0646 \u0632\u0627\u06cc\u0645\u0627\u0646 \u0634\u0646\u0627\u062e\u062a\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f \u0646\u0647 \u0627\u06cc\u0646 \u062a\u0627\u0628\u0644\u0648\u06cc \u062d\u0627\u062f."],
  },
  (28, 203): {
   "topic": "diabeticMacrosomiaCesarean",
   "lead": "\u062f\u06cc\u0627\u0628\u062a \u0622\u0634\u06a9\u0627\u0631 \u062a\u062d\u062a \u062f\u0631\u0645\u0627\u0646 \u0628\u0627 \u0627\u0646\u0633\u0648\u0644\u06cc\u0646 \u0648 \u0648\u0632\u0646 \u062a\u062e\u0645\u06cc\u0646\u06cc \u062c\u0646\u06cc\u0646 \u0628\u06cc\u0634 \u0627\u0632 \u06f4\u06f5\u06f0\u06f0 \u06af\u0631\u0645 \u062f\u0631 \u06f3\u06f8 \u0647\u0641\u062a\u0647: \u0633\u0632\u0627\u0631\u06cc\u0646 \u0627\u0644\u06a9\u062a\u06cc\u0648.",
   "interpretation": "\u062f\u0631 \u062f\u06cc\u0627\u0628\u062a \u0645\u0627\u062f\u0631\u060c \u0648\u0632\u0646 \u062a\u062e\u0645\u06cc\u0646\u06cc \u0628\u06cc\u0634 \u0627\u0632 \u06f4\u06f5\u06f0\u06f0 \u06af\u0631\u0645 \u062e\u0637\u0631 \u06af\u06cc\u0631 \u0627\u0641\u062a\u0627\u062f\u0646 \u0634\u0627\u0646\u0647 \u0631\u0627 \u0628\u0627\u0644\u0627 \u0645\u06cc\u200c\u0628\u0631\u062f \u0648 \u062f\u0631 \u0627\u06cc\u0646 \u0633\u0646 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc\u060c \u0633\u0632\u0627\u0631\u06cc\u0646 \u0627\u0644\u06a9\u062a\u06cc\u0648 \u062a\u0648\u0635\u06cc\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f\u061b \u0627\u0646\u062a\u0638\u0627\u0631 \u0628\u0631\u0627\u06cc \u0632\u0627\u06cc\u0645\u0627\u0646 \u062e\u0648\u062f\u0628\u0647\u200c\u062e\u0648\u062f\u060c \u0627\u0644\u0642\u0627 \u0628\u0627 \u0627\u06a9\u0633\u06cc\u200c\u062a\u0648\u0633\u06cc\u0646 \u06cc\u0627 \u0645\u06cc\u0632\u0648\u067e\u0631\u0648\u0633\u062a\u0648\u0644 \u0648\u0627\u0698\u06cc\u0646\u0627\u0644 \u062f\u0631 \u0627\u06cc\u0646 \u062f\u0631\u062c\u0647 \u0627\u0632 \u0645\u0627\u06a9\u0631\u0648\u0632\u0648\u0645\u06cc \u062e\u0637\u0631\u0646\u0627\u06a9 \u062a\u0644\u0642\u06cc \u0645\u06cc\u200c\u0634\u0648\u062f.",
   "reasons": ["\u0627\u0646\u062a\u0638\u0627\u0631 \u0628\u0631\u0627\u06cc \u0632\u0627\u06cc\u0645\u0627\u0646 \u062e\u0648\u062f\u0628\u0647\u200c\u062e\u0648\u062f \u062f\u0631 \u0645\u0627\u06a9\u0631\u0648\u0632\u0648\u0645\u06cc \u0628\u0627\u0644\u0627\u06cc \u06f4\u06f5\u06f0\u06f0 \u06af\u0631\u0645 \u067e\u0631\u062e\u0637\u0631 \u0627\u0633\u062a.", "\u0645\u06cc\u0632\u0648\u067e\u0631\u0648\u0633\u062a\u0648\u0644 \u0648\u0627\u0698\u06cc\u0646\u0627\u0644 \u0628\u0631\u0627\u06cc \u0627\u0644\u0642\u0627\u06cc \u0632\u0627\u06cc\u0645\u0627\u0646 \u062f\u0631 \u0627\u06cc\u0646 \u062e\u0637\u0631 \u06af\u06cc\u0631 \u0627\u0641\u062a\u0627\u062f\u0646 \u0634\u0627\u0646\u0647 \u0645\u0646\u0627\u0633\u0628 \u0646\u06cc\u0633\u062a.", "\u0627\u0644\u0642\u0627 \u0628\u0627 \u0627\u06a9\u0633\u06cc\u200c\u062a\u0648\u0633\u06cc\u0646 \u0646\u06cc\u0632 \u062e\u0637\u0631 \u06af\u06cc\u0631 \u0627\u0641\u062a\u0627\u062f\u0646 \u0634\u0627\u0646\u0647 \u0631\u0627 \u06a9\u0645 \u0646\u0645\u06cc\u200c\u06a9\u0646\u062f.", "\u0633\u0632\u0627\u0631\u06cc\u0646 \u0627\u0644\u06a9\u062a\u06cc\u0648 \u062f\u0631 \u0645\u0627\u06a9\u0631\u0648\u0632\u0648\u0645\u06cc \u0634\u062f\u06cc\u062f \u062f\u06cc\u0627\u0628\u062a\u06cc \u062a\u0648\u0635\u06cc\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d."],
  },
  (28, 204): {
   "topic": "oligohydramniosRenal",
   "lead": "\u0627\u0644\u06cc\u06af\u0648\u0647\u06cc\u062f\u0631\u0627\u0645\u0646\u06cc\u0648\u0633 \u0634\u062f\u06cc\u062f \u062f\u0631 \u06f2\u06f8 \u0647\u0641\u062a\u0647 \u0628\u062f\u0648\u0646 \u0622\u0628\u0631\u06cc\u0632\u0634: \u0646\u0627\u0647\u0646\u062c\u0627\u0631\u06cc \u06a9\u0644\u06cc\u0648\u06cc \u062c\u0646\u06cc\u0646 \u0639\u0627\u0645\u0644 \u0622\u0646 \u0627\u0633\u062a.",
   "interpretation": "\u067e\u0633 \u0627\u0632 \u0647\u0641\u062a\u0647\u0654 \u06f2\u06f0\u060c \u0627\u062f\u0631\u0627\u0631 \u062c\u0646\u06cc\u0646 \u0645\u0646\u0628\u0639 \u0627\u0635\u0644\u06cc \u0645\u0627\u06cc\u0639 \u0622\u0645\u0646\u06cc\u0648\u062a\u06cc\u06a9 \u0627\u0633\u062a\u061b \u0622\u0698\u0646\u0632\u06cc \u06cc\u0627 \u0627\u0646\u0633\u062f\u0627\u062f \u0631\u0627\u0647\u200c\u0647\u0627\u06cc \u0627\u062f\u0631\u0627\u0631\u06cc \u0628\u0627 \u06a9\u0627\u0647\u0634 \u062a\u0648\u0644\u06cc\u062f \u0627\u062f\u0631\u0627\u0631\u060c \u0627\u0644\u06cc\u06af\u0648\u0647\u06cc\u062f\u0631\u0627\u0645\u0646\u06cc\u0648\u0633 \u0634\u062f\u06cc\u062f \u0645\u06cc\u200c\u0633\u0627\u0632\u062f. \u0627\u0646\u0633\u062f\u0627\u062f \u062f\u0633\u062a\u06af\u0627\u0647 \u06af\u0648\u0627\u0631\u0634 \u0648 \u0641\u06cc\u0633\u062a\u0648\u0644 \u062a\u0631\u0627\u06a9\u0626\u0648\u0627\u0632\u0648\u0641\u0627\u0698\u06cc\u0627\u0644 \u0645\u0639\u0645\u0648\u0644\u0627\u064b \u067e\u0644\u06cc\u200c\u0647\u06cc\u062f\u0631\u0627\u0645\u0646\u06cc\u0648\u0633 \u0645\u06cc\u200c\u062f\u0647\u0646\u062f \u0648 \u0646\u0627\u0647\u0646\u062c\u0627\u0631\u06cc\u200c\u0647\u0627\u06cc \u0633\u06cc\u0633\u062a\u0645 \u0639\u0635\u0628\u06cc \u0645\u0631\u06a9\u0632\u06cc \u062f\u0631 \u0627\u0644\u06af\u0648\u06cc \u0645\u0635\u0631\u0641 \u0645\u0627\u06cc\u0639 \u0646\u0642\u0634 \u0627\u0635\u0644\u06cc \u062f\u0631 \u0627\u0644\u06cc\u06af\u0648\u0647\u06cc\u062f\u0631\u0627\u0645\u0646\u06cc\u0648\u0633 \u0646\u062f\u0627\u0631\u0646\u062f.",
   "reasons": ["\u0646\u0627\u0647\u0646\u062c\u0627\u0631\u06cc \u0633\u06cc\u0633\u062a\u0645 \u0639\u0635\u0628\u06cc \u0645\u0631\u06a9\u0632\u06cc \u0639\u0644\u062a \u0627\u0635\u0644\u06cc \u0627\u0644\u06cc\u06af\u0648\u0647\u06cc\u062f\u0631\u0627\u0645\u0646\u06cc\u0648\u0633 \u0634\u062f\u06cc\u062f \u0646\u06cc\u0633\u062a.", "\u0646\u0627\u0647\u0646\u062c\u0627\u0631\u06cc \u06a9\u0644\u06cc\u0648\u06cc \u0628\u0627 \u06a9\u0627\u0647\u0634 \u062a\u0648\u0644\u06cc\u062f \u0627\u062f\u0631\u0627\u0631 \u0627\u0644\u06cc\u06af\u0648\u0647\u06cc\u062f\u0631\u0627\u0645\u0646\u06cc\u0648\u0633 \u0634\u062f\u06cc\u062f \u0645\u06cc\u200c\u0633\u0627\u0632\u062f\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0641\u06cc\u0633\u062a\u0648\u0644 \u062a\u0631\u0627\u06a9\u0626\u0648\u0627\u0632\u0648\u0641\u0627\u0698\u06cc\u0627\u0644 \u0628\u06cc\u0634\u062a\u0631 \u0628\u0627 \u067e\u0644\u06cc\u200c\u0647\u06cc\u062f\u0631\u0627\u0645\u0646\u06cc\u0648\u0633 \u0647\u0645\u0631\u0627\u0647 \u0627\u0633\u062a.", "\u0627\u0646\u0633\u062f\u0627\u062f \u06af\u0648\u0627\u0631\u0634\u06cc \u0646\u06cc\u0632 \u0645\u0639\u0645\u0648\u0644\u0627\u064b \u067e\u0644\u06cc\u200c\u0647\u06cc\u062f\u0631\u0627\u0645\u0646\u06cc\u0648\u0633 \u0645\u06cc\u200c\u062f\u0647\u062f \u0646\u0647 \u0627\u0644\u06cc\u06af\u0648\u0647\u06cc\u062f\u0631\u0627\u0645\u0646\u06cc\u0648\u0633."],
  },
  (28, 205): {
   "topic": "eclampsiaMgDuration",
   "lead": "\u062a\u0634\u0646\u062c \u067e\u0633 \u0627\u0632 \u0632\u0627\u06cc\u0645\u0627\u0646 \u062f\u0631 \u0628\u06cc\u0645\u0627\u0631 \u062a\u062d\u062a \u0633\u0648\u0644\u0641\u0627\u062a \u0645\u0646\u06cc\u0632\u06cc\u0645: \u0627\u062f\u0627\u0645\u0647\u0654 \u062f\u0627\u0631\u0648 \u062a\u0627 \u06f2\u06f4 \u0633\u0627\u0639\u062a \u067e\u0633 \u0627\u0632 \u062a\u0634\u0646\u062c.",
   "interpretation": "\u0632\u0645\u0627\u0646 \u0642\u0637\u0639 \u0633\u0648\u0644\u0641\u0627\u062a \u0645\u0646\u06cc\u0632\u06cc\u0645 \u062f\u0631 \u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc\u060c \u06f2\u06f4 \u0633\u0627\u0639\u062a \u067e\u0633 \u0627\u0632 \u0622\u062e\u0631\u06cc\u0646 \u062a\u0634\u0646\u062c \u0627\u0633\u062a\u060c \u0646\u0647 \u0627\u0632 \u0632\u0645\u0627\u0646 \u0634\u0631\u0648\u0639 \u062f\u0627\u0631\u0648 \u06cc\u0627 \u0627\u0632 \u0632\u0645\u0627\u0646 \u0632\u0627\u06cc\u0645\u0627\u0646\u061b \u062f\u0631 \u0627\u06cc\u0646 \u0628\u06cc\u0645\u0627\u0631 \u06a9\u0647 \u0633\u0647 \u0633\u0627\u0639\u062a \u067e\u0633 \u0627\u0632 \u0632\u0627\u06cc\u0645\u0627\u0646 \u062f\u0686\u0627\u0631 \u062a\u0634\u0646\u062c \u0634\u062f\u0647\u060c \u0634\u0645\u0627\u0631\u0634 \u0627\u0632 \u062e\u0648\u062f \u062a\u0634\u0646\u062c \u0622\u063a\u0627\u0632 \u0645\u06cc\u200c\u0634\u0648\u062f \u0648 \u0627\u062f\u0627\u0645\u0647\u0654 \u06f4\u06f8 \u0633\u0627\u0639\u062a\u0647 \u0628\u06cc\u0634 \u0627\u0632 \u062d\u062f \u0644\u0627\u0632\u0645 \u0648 \u0642\u0637\u0639 \u067e\u06cc\u0634 \u0627\u0632 \u06f2\u06f4 \u0633\u0627\u0639\u062a \u0646\u0627\u06a9\u0627\u0641\u06cc \u0627\u0633\u062a.",
   "reasons": ["\u0634\u0645\u0627\u0631\u0634 \u0627\u0632 \u0632\u0645\u0627\u0646 \u0634\u0631\u0648\u0639 \u062f\u0627\u0631\u0648 \u0645\u0644\u0627\u06a9 \u0642\u0637\u0639 \u0633\u0648\u0644\u0641\u0627\u062a \u0646\u06cc\u0633\u062a.", "\u0632\u0645\u0627\u0646 \u0632\u0627\u06cc\u0645\u0627\u0646 \u0645\u0644\u0627\u06a9 \u0642\u0637\u0639 \u0633\u0648\u0644\u0641\u0627\u062a \u0645\u0646\u06cc\u0632\u06cc\u0645 \u0646\u06cc\u0633\u062a.", "\u062f\u0631\u0645\u0627\u0646 \u062a\u0627 \u06f2\u06f4 \u0633\u0627\u0639\u062a \u067e\u0633 \u0627\u0632 \u0622\u062e\u0631\u06cc\u0646 \u062a\u0634\u0646\u062c \u0627\u062f\u0627\u0645\u0647 \u0645\u06cc\u200c\u06cc\u0627\u0628\u062f\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0627\u062f\u0627\u0645\u0647\u0654 \u0633\u0648\u0644\u0641\u0627\u062a \u062a\u0627 \u06f4\u06f8 \u0633\u0627\u0639\u062a \u067e\u0633 \u0627\u0632 \u062a\u0634\u0646\u062c \u0628\u06cc\u0634 \u0627\u0632 \u062d\u062f \u0644\u0627\u0632\u0645 \u0627\u0633\u062a."],
  },
  (28, 206): {
   "topic": "mullerianAgenesisUrinary",
   "lead": "\u0622\u0645\u0646\u0648\u0631\u0647\u0654 \u0627\u0648\u0644\u06cc\u0647 \u0628\u0627 \u06a9\u0627\u0631\u06cc\u0648\u062a\u0627\u06cc\u067e \u06f4\u06f6XX \u0648 \u0646\u0628\u0648\u062f \u0631\u062d\u0645 \u062f\u0631 \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc: \u0647\u0645\u0631\u0627\u0647\u06cc \u0628\u0627 \u0646\u0627\u0647\u0646\u062c\u0627\u0631\u06cc\u200c\u0647\u0627\u06cc \u0627\u062f\u0631\u0627\u0631\u06cc.",
   "interpretation": "\u0646\u0628\u0648\u062f \u0631\u062d\u0645 \u062f\u0631 \u062f\u062e\u062a\u0631 \u0628\u0627 \u06a9\u0627\u0631\u06cc\u0648\u062a\u0627\u06cc\u067e \u06f4\u06f6XX \u0648 \u0639\u0645\u0644\u06a9\u0631\u062f \u062a\u062e\u0645\u062f\u0627\u0646\u06cc \u0637\u0628\u06cc\u0639\u06cc\u060c \u0622\u0698\u0646\u0632\u06cc \u0645\u0648\u0644\u0631\u06cc\u0646 (\u0633\u0646\u062f\u0631\u0645 \u0631\u0627\u06a9\u06cc\u062a\u0627\u0646\u0633\u06a9\u06cc) \u0627\u0633\u062a \u0648 \u0686\u0648\u0646 \u062f\u0633\u062a\u06af\u0627\u0647 \u0627\u062f\u0631\u0627\u0631\u06cc \u0648 \u0645\u062c\u0627\u0631\u06cc \u0645\u0648\u0644\u0631\u06cc\u0646 \u0627\u0632 \u0647\u0645\u0633\u0627\u06cc\u06af\u06cc \u062c\u0646\u06cc\u0646\u06cc \u06cc\u06a9\u0633\u0627\u0646\u06cc \u062a\u06a9\u0627\u0645\u0644 \u0645\u06cc\u200c\u06cc\u0627\u0628\u0646\u062f\u060c \u0646\u0627\u0647\u0646\u062c\u0627\u0631\u06cc\u200c\u0647\u0627\u06cc \u062f\u0633\u062a\u06af\u0627\u0647 \u0627\u062f\u0631\u0627\u0631\u06cc \u0634\u0627\u06cc\u0639\u200c\u062a\u0631\u06cc\u0646 \u0647\u0645\u0631\u0627\u0647\u06cc \u0622\u0646 \u0647\u0633\u062a\u0646\u062f. \u0646\u0627\u0647\u0646\u062c\u0627\u0631\u06cc\u200c\u0647\u0627\u06cc \u0627\u0633\u06a9\u0644\u062a\u06cc \u0648 \u062a\u0646\u0641\u0633\u06cc \u0647\u0645\u0631\u0627\u0647\u06cc \u0634\u0627\u06cc\u0639 \u0627\u06cc\u0646 \u0633\u0646\u062f\u0631\u0645 \u0646\u06cc\u0633\u062a\u0646\u062f \u0648 \u0645\u0634\u06a9\u0644\u0627\u062a \u06af\u0648\u0634 \u0648 \u0634\u0646\u0648\u0627\u06cc\u06cc \u0628\u06cc\u0634\u062a\u0631 \u062f\u0631 \u0633\u0646\u062f\u0631\u0645\u200c\u0647\u0627\u06cc\u06cc \u0645\u0627\u0646\u0646\u062f \u062a\u0631\u0646\u0631 \u062f\u06cc\u062f\u0647 \u0645\u06cc\u200c\u0634\u0648\u0646\u062f.",
   "reasons": ["\u0646\u0627\u0647\u0646\u062c\u0627\u0631\u06cc \u0627\u0633\u06a9\u0644\u062a\u06cc \u0647\u0645\u0631\u0627\u0647\u06cc \u0634\u0627\u06cc\u0639 \u0622\u0698\u0646\u0632\u06cc \u0645\u0648\u0644\u0631\u06cc\u0646 \u0646\u06cc\u0633\u062a.", "\u0647\u0645\u0631\u0627\u0647\u06cc \u062a\u0646\u0641\u0633\u06cc \u0634\u0627\u06cc\u0639 \u0628\u0631\u0627\u06cc \u0627\u06cc\u0646 \u0633\u0646\u062f\u0631\u0645 \u0634\u0646\u0627\u062e\u062a\u0647 \u0646\u0634\u062f\u0647 \u0627\u0633\u062a.", "\u0646\u0627\u0647\u0646\u062c\u0627\u0631\u06cc \u062f\u0633\u062a\u06af\u0627\u0647 \u0627\u062f\u0631\u0627\u0631\u06cc \u0634\u0627\u06cc\u0639\u200c\u062a\u0631\u06cc\u0646 \u0647\u0645\u0631\u0627\u0647\u06cc \u0622\u0698\u0646\u0632\u06cc \u0645\u0648\u0644\u0631\u06cc\u0646 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0645\u0634\u06a9\u0644\u0627\u062a \u06af\u0648\u0634 \u0648 \u0634\u0646\u0648\u0627\u06cc\u06cc \u0628\u06cc\u0634\u062a\u0631 \u062f\u0631 \u0633\u0646\u062f\u0631\u0645\u200c\u0647\u0627\u06cc\u06cc \u0645\u0627\u0646\u0646\u062f \u062a\u0631\u0646\u0631 \u0645\u0637\u0631\u062d \u0645\u06cc\u200c\u0634\u0648\u0646\u062f."],
  },
  (28, 207): {
   "topic": "twinSingleDeathDc",
   "lead": "\u0641\u0648\u062a \u06cc\u06a9 \u062c\u0646\u06cc\u0646 \u062f\u0631 \u062f\u0648\u0642\u0644\u0648\u06cc\u06cc \u062f\u06cc\u200c\u06a9\u0648\u0631\u06cc\u0648\u0646 \u062f\u0631 \u06f3\u06f0 \u0647\u0641\u062a\u0647: \u0645\u062f\u06cc\u0631\u06cc\u062a \u0627\u0646\u062a\u0638\u0627\u0631\u06cc \u0648 \u067e\u0627\u06cc\u0634.",
   "interpretation": "\u062f\u0631 \u062f\u0648\u0642\u0644\u0648\u06cc\u06cc \u062f\u06cc\u200c\u06a9\u0648\u0631\u06cc\u0648\u0646\u060c \u0641\u0648\u062a \u06cc\u06a9 \u062c\u0646\u06cc\u0646 \u0628\u0647\u200c\u0639\u0644\u062a \u062c\u062f\u0627\u06cc\u06cc \u06af\u0631\u062f\u0634 \u062e\u0648\u0646 \u062e\u0637\u0631 \u0645\u0633\u062a\u0642\u06cc\u0645 \u0628\u0631\u0627\u06cc \u0642\u0644 \u0632\u0646\u062f\u0647 \u0627\u06cc\u062c\u0627\u062f \u0646\u0645\u06cc\u200c\u06a9\u0646\u062f \u0648 \u0645\u062f\u06cc\u0631\u06cc\u062a \u0627\u0646\u062a\u0638\u0627\u0631\u06cc \u0628\u0627 \u067e\u0627\u06cc\u0634 \u0642\u0644 \u0632\u0646\u062f\u0647 \u0648 \u0628\u0631\u0631\u0633\u06cc \u0648\u0636\u0639\u06cc\u062a \u0627\u0646\u0639\u0642\u0627\u062f\u06cc \u0645\u0627\u062f\u0631 \u0645\u0646\u0627\u0633\u0628 \u0627\u0633\u062a\u061b \u0647\u067e\u0627\u0631\u06cc\u0646 \u067e\u0631\u0648\u0641\u06cc\u0644\u0627\u06a9\u062a\u06cc\u06a9 \u0631\u0648\u062a\u06cc\u0646 \u062a\u0648\u0635\u06cc\u0647 \u0646\u0645\u06cc\u200c\u0634\u0648\u062f\u060c \u062a\u0648\u06a9\u0648\u0644\u06cc\u062a\u06cc\u06a9 \u0627\u0646\u062f\u06cc\u06a9\u0627\u0633\u06cc\u0648\u0646 \u0646\u062f\u0627\u0631\u062f \u0648 \u0633\u0632\u0627\u0631\u06cc\u0646 \u0627\u0648\u0631\u0698\u0627\u0646\u0633 \u0641\u0642\u0637 \u0628\u0627 \u0634\u0648\u0627\u0647\u062f \u0646\u0627\u0631\u0633\u0627\u06cc\u06cc \u0642\u0644 \u0632\u0646\u062f\u0647 \u06cc\u0627 \u0627\u0646\u062f\u06cc\u06a9\u0627\u0633\u06cc\u0648\u0646 \u0645\u0627\u062f\u0631\u06cc \u0627\u0646\u062c\u0627\u0645 \u0645\u06cc\u200c\u0634\u0648\u062f.",
   "reasons": ["\u0647\u067e\u0627\u0631\u06cc\u0646 \u067e\u0631\u0648\u0641\u06cc\u0644\u0627\u06a9\u0633\u06cc \u0631\u0648\u062a\u06cc\u0646 \u062f\u0631 \u0641\u0648\u062a \u06cc\u06a9 \u0642\u0644 \u062f\u06cc\u200c\u06a9\u0648\u0631\u06cc\u0648\u0646 \u062a\u0648\u0635\u06cc\u0647 \u0646\u0645\u06cc\u200c\u0634\u0648\u062f.", "\u0645\u062f\u06cc\u0631\u06cc\u062a \u0627\u0646\u062a\u0638\u0627\u0631\u06cc \u0647\u0645\u0631\u0627\u0647 \u067e\u0627\u06cc\u0634 \u0627\u0642\u062f\u0627\u0645 \u0645\u0646\u0627\u0633\u0628 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u062a\u0648\u06a9\u0648\u0644\u06cc\u062a\u06cc\u06a9 \u062f\u0631 \u0627\u06cc\u0646 \u0648\u0636\u0639\u06cc\u062a \u0627\u0646\u062f\u06cc\u06a9\u0627\u0633\u06cc\u0648\u0646 \u0646\u062f\u0627\u0631\u062f.", "\u0633\u0632\u0627\u0631\u06cc\u0646 \u0627\u0648\u0631\u0698\u0627\u0646\u0633 \u0628\u062f\u0648\u0646 \u0634\u0648\u0627\u0647\u062f \u0646\u0627\u0631\u0633\u0627\u06cc\u06cc \u0642\u0644 \u0632\u0646\u062f\u0647 \u0644\u0627\u0632\u0645 \u0646\u06cc\u0633\u062a."],
  },
  (28, 208): {
   "topic": "infertilityWorkupLaparoscopy",
   "lead": "\u0644\u0627\u067e\u0627\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u062c\u0632\u0621 \u0628\u0631\u0631\u0633\u06cc\u200c\u0647\u0627\u06cc \u0627\u0648\u0644\u06cc\u0647\u0654 \u0632\u0648\u062c \u0646\u0627\u0628\u0627\u0631\u0648\u0631 \u0646\u06cc\u0633\u062a.",
   "interpretation": "\u0628\u0631\u0631\u0633\u06cc \u0627\u0648\u0644\u06cc\u0647\u0654 \u0632\u0648\u062c \u0646\u0627\u0628\u0627\u0631\u0648\u0631 \u0634\u0627\u0645\u0644 \u0622\u0646\u0627\u0644\u06cc\u0632 \u0627\u0633\u067e\u0631\u0645\u060c \u0645\u0633\u062a\u0646\u062f\u0633\u0627\u0632\u06cc \u062a\u062e\u0645\u06a9\u200c\u06af\u0630\u0627\u0631\u06cc \u0648 \u062f\u0631 \u0635\u0648\u0631\u062a \u0644\u0632\u0648\u0645 \u0647\u06cc\u0633\u062a\u0631\u0648\u0633\u0627\u0644\u067e\u0646\u06af\u0648\u06af\u0631\u0627\u0641\u06cc \u0628\u0631\u0627\u06cc \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u0628\u0627\u0632 \u0628\u0648\u062f\u0646 \u0644\u0648\u0644\u0647\u200c\u0647\u0627 \u0627\u0633\u062a\u061b \u0644\u0627\u067e\u0627\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u0631\u0648\u0634 \u062a\u0647\u0627\u062c\u0645\u06cc \u0627\u0633\u062a \u0648 \u062f\u0631 \u067e\u0644\u0647\u0654 \u067e\u0627\u06cc\u0627\u0646\u06cc \u0642\u0631\u0627\u0631 \u062f\u0627\u0631\u062f \u0648 \u062a\u0646\u0647\u0627 \u0628\u0627 \u0634\u06a9 \u0642\u0648\u06cc \u0628\u0647 \u0686\u0633\u0628\u0646\u062f\u06af\u06cc \u06cc\u0627 \u0627\u0646\u062f\u0648\u0645\u062a\u0631\u06cc\u0648\u0632 \u067e\u06cc\u0634\u0631\u0641\u062a\u0647 \u06cc\u0627 \u067e\u0633 \u0627\u0632 \u0628\u0631\u0631\u0633\u06cc\u200c\u0647\u0627\u06cc \u0646\u0627\u062a\u0645\u0627\u0645 \u062f\u0631\u062e\u0648\u0627\u0633\u062a \u0645\u06cc\u200c\u0634\u0648\u062f.",
   "reasons": ["\u0622\u0646\u0627\u0644\u06cc\u0632 \u0627\u0633\u067e\u0631\u0645 \u062c\u0632\u0621 \u0628\u0631\u0631\u0633\u06cc\u200c\u0647\u0627\u06cc \u0627\u0648\u0644\u06cc\u0647 \u0627\u0633\u062a.", "\u0645\u0633\u062a\u0646\u062f\u0633\u0627\u0632\u06cc \u062a\u062e\u0645\u06a9\u200c\u06af\u0630\u0627\u0631\u06cc \u0627\u0632 \u06af\u0627\u0645\u200c\u0647\u0627\u06cc \u0627\u0648\u0644\u06cc\u0647\u0654 \u0628\u0631\u0631\u0633\u06cc \u0627\u0633\u062a.", "\u0647\u06cc\u0633\u062a\u0631\u0648\u0633\u0627\u0644\u067e\u0646\u06af\u0648\u06af\u0631\u0627\u0641\u06cc \u062f\u0631 \u0628\u0631\u0631\u0633\u06cc \u0627\u0648\u0644\u06cc\u0647\u0654 \u0628\u0627\u0632 \u0628\u0648\u062f\u0646 \u0644\u0648\u0644\u0647\u200c\u0647\u0627 \u0627\u0646\u062c\u0627\u0645 \u0645\u06cc\u200c\u0634\u0648\u062f.", "\u0644\u0627\u067e\u0627\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u062c\u0632\u0621 \u0628\u0631\u0631\u0633\u06cc \u0627\u0648\u0644\u06cc\u0647 \u0646\u06cc\u0633\u062a \u0648 \u062f\u0631 \u067e\u0644\u0647\u0654 \u067e\u0627\u06cc\u0627\u0646\u06cc \u0642\u0631\u0627\u0631 \u062f\u0627\u0631\u062f\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d."],
  },
  (28, 209): {
   "topic": "abruptionExpectantSteroid",
   "lead": "\u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u062e\u0641\u06cc\u0641 \u0628\u0627 \u0647\u0645\u0627\u062a\u0648\u0645 \u06a9\u0648\u0686\u06a9 \u067e\u0634\u062a \u062c\u0641\u062a \u0648 \u0645\u0627\u062f\u0631 \u0648 \u062c\u0646\u06cc\u0646 \u067e\u0627\u06cc\u062f\u0627\u0631 \u062f\u0631 \u06f3\u06f2 \u0647\u0641\u062a\u0647: \u067e\u0627\u06cc\u0634 \u0648 \u0628\u062a\u0627\u0645\u062a\u0627\u0632\u0648\u0646.",
   "interpretation": "\u062f\u0631 \u062f\u06a9\u0648\u0644\u0645\u0627\u0646 \u062e\u0641\u06cc\u0641 \u0628\u0627 \u0639\u0644\u0627\u0626\u0645 \u062d\u06cc\u0627\u062a\u06cc \u067e\u0627\u06cc\u062f\u0627\u0631 \u0648 \u0628\u062f\u0648\u0646 \u062f\u06cc\u0633\u062a\u0631\u0633 \u062c\u0646\u06cc\u0646\u06cc \u0648 \u0647\u0645\u0627\u062a\u0648\u0645 \u06a9\u0648\u0686\u06a9\u060c \u067e\u0627\u06cc\u0634 \u062f\u0642\u06cc\u0642 \u0645\u0627\u062f\u0631 \u0648 \u062c\u0646\u06cc\u0646 \u0647\u0645\u0631\u0627\u0647 \u0628\u0627 \u06a9\u0648\u0631\u062a\u06cc\u06a9\u0648\u0627\u0633\u062a\u0631\u0648\u0626\u06cc\u062f \u0628\u0631\u0627\u06cc \u0628\u0644\u0648\u063a \u0631\u06cc\u0647 \u062f\u0631 \u0633\u0646 \u067e\u06cc\u0634 \u0627\u0632 \u06f3\u06f4 \u0647\u0641\u062a\u0647 \u0645\u0646\u0637\u0642\u06cc \u0627\u0633\u062a. \u062e\u062a\u0645 \u0641\u0648\u0631\u06cc \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0648 \u0633\u0632\u0627\u0631\u06cc\u0646 \u0627\u0648\u0631\u0698\u0627\u0646\u0633\u06cc \u062f\u0631 \u0646\u0628\u0648\u062f \u062a\u0647\u062f\u06cc\u062f \u0645\u0627\u062f\u0631 \u06cc\u0627 \u062c\u0646\u06cc\u0646 \u0644\u0627\u0632\u0645 \u0646\u06cc\u0633\u062a \u0648 \u0622\u0645\u0646\u06cc\u0648\u0633\u0646\u062a\u0632 \u0628\u0631\u0627\u06cc \u062a\u0639\u06cc\u06cc\u0646 \u0628\u0644\u0648\u063a \u0631\u06cc\u0647 \u0631\u0648\u0634\u06cc \u0645\u0646\u0633\u0648\u062e \u0648 \u067e\u0631\u062e\u0637\u0631 \u0627\u0633\u062a.",
   "reasons": ["\u062e\u062a\u0645 \u0641\u0648\u0631\u06cc \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062f\u0631 \u0634\u0631\u0627\u06cc\u0637 \u067e\u0627\u06cc\u062f\u0627\u0631 \u0648 \u0647\u0645\u0627\u062a\u0648\u0645 \u06a9\u0648\u0686\u06a9 \u0644\u0627\u0632\u0645 \u0646\u06cc\u0633\u062a.", "\u0633\u0632\u0627\u0631\u06cc\u0646 \u0627\u0648\u0631\u0698\u0627\u0646\u0633\u06cc \u062f\u0631 \u0627\u06cc\u0646 \u0648\u0636\u0639\u06cc\u062a \u0627\u0646\u062f\u06cc\u06a9\u0627\u0633\u06cc\u0648\u0646 \u0646\u062f\u0627\u0631\u062f.", "\u067e\u0627\u06cc\u0634 \u0648 \u062a\u062c\u0648\u06cc\u0632 \u0628\u062a\u0627\u0645\u062a\u0627\u0632\u0648\u0646 \u0628\u0647\u062a\u0631\u06cc\u0646 \u0627\u0642\u062f\u0627\u0645 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0622\u0645\u0646\u06cc\u0648\u0633\u0646\u062a\u0632 \u0628\u0631\u0627\u06cc \u062a\u0639\u06cc\u06cc\u0646 \u0628\u0644\u0648\u063a \u0631\u06cc\u0647 \u0631\u0648\u0634\u06cc \u0645\u0646\u0633\u0648\u062e \u0648 \u067e\u0631\u062e\u0637\u0631 \u0627\u0633\u062a."],
  },
  (28, 210): {
   "topic": "safeAntibioticPregnancy",
   "lead": "\u062a\u062a\u0631\u0627\u0633\u0627\u06cc\u06a9\u0644\u06cc\u0646 \u0622\u0646\u062a\u06cc\u200c\u0628\u06cc\u0648\u062a\u06cc\u06a9\u06cc \u0627\u0633\u062a \u06a9\u0647 \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062a\u0648\u0635\u06cc\u0647 \u0646\u0645\u06cc\u200c\u0634\u0648\u062f.",
   "interpretation": "\u062a\u062a\u0631\u0627\u0633\u0627\u06cc\u06a9\u0644\u06cc\u0646 \u0628\u0647\u200c\u062f\u0644\u06cc\u0644 \u0631\u0633\u0648\u0628 \u062f\u0631 \u0627\u0633\u062a\u062e\u0648\u0627\u0646 \u0648 \u062f\u0646\u062f\u0627\u0646\u200c\u0647\u0627\u06cc \u062f\u0631 \u062d\u0627\u0644 \u062a\u06a9\u0627\u0645\u0644 \u062c\u0646\u06cc\u0646 (\u062a\u063a\u06cc\u06cc\u0631 \u0631\u0646\u06af \u062f\u0646\u062f\u0627\u0646 \u0648 \u0645\u0647\u0627\u0631 \u0631\u0634\u062f \u0627\u0633\u062a\u062e\u0648\u0627\u0646\u06cc) \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0645\u0646\u0639 \u062f\u0627\u0631\u062f\u061b \u0622\u0645\u067e\u06cc\u200c\u0633\u06cc\u0644\u06cc\u0646\u060c \u0627\u0631\u06cc\u062a\u0631\u0648\u0645\u0627\u06cc\u0633\u06cc\u0646 \u0648 \u0646\u06cc\u062a\u0631\u0648\u0641\u0648\u0631\u0627\u0646\u062a\u0648\u0626\u06cc\u0646 \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0628\u0647\u200c\u0637\u0648\u0631 \u06a9\u0644\u06cc \u0627\u06cc\u0645\u0646 \u0648 \u0642\u0627\u0628\u0644 \u0627\u0633\u062a\u0641\u0627\u062f\u0647\u200c\u0627\u0646\u062f \u0648 \u062f\u0631 \u0645\u0648\u0627\u0631\u062f \u0645\u0646\u0627\u0633\u0628 \u062a\u062c\u0648\u06cc\u0632 \u0645\u06cc\u200c\u0634\u0648\u0646\u062f.",
   "reasons": ["\u0622\u0645\u067e\u06cc\u200c\u0633\u06cc\u0644\u06cc\u0646 \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0642\u0627\u0628\u0644 \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0627\u0633\u062a.", "\u0627\u0631\u06cc\u062a\u0631\u0648\u0645\u0627\u06cc\u0633\u06cc\u0646 \u062c\u0632\u0648 \u0622\u0646\u062a\u06cc\u200c\u0628\u06cc\u0648\u062a\u06cc\u06a9\u200c\u0647\u0627\u06cc \u0646\u0633\u0628\u062a\u0627\u064b \u0628\u06cc\u200c\u062e\u0637\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0627\u0633\u062a.", "\u062a\u062a\u0631\u0627\u0633\u0627\u06cc\u06a9\u0644\u06cc\u0646 \u0628\u0647\u200c\u062f\u0644\u06cc\u0644 \u0627\u062b\u0631 \u0628\u0631 \u062f\u0646\u062f\u0627\u0646 \u0648 \u0627\u0633\u062a\u062e\u0648\u0627\u0646 \u062c\u0646\u06cc\u0646 \u062a\u0648\u0635\u06cc\u0647 \u0646\u0645\u06cc\u200c\u0634\u0648\u062f\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0646\u06cc\u062a\u0631\u0648\u0641\u0648\u0631\u0627\u0646\u062a\u0648\u0626\u06cc\u0646 \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062f\u0631 \u062f\u0648\u0631\u0647\u200c\u0647\u0627\u06cc \u0645\u0646\u0627\u0633\u0628 \u0642\u0627\u0628\u0644 \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0627\u0633\u062a."],
  },
  (28, 211): {
   "topic": "inevitableAbortion",
   "lead": "\u0645\u0634\u0627\u0647\u062f\u0647\u0654 \u0633\u0627\u06a9 \u062d\u0627\u0645\u0644\u06af\u06cc \u062f\u0631 \u062f\u0647\u0627\u0646\u0647\u0654 \u0631\u062d\u0645 \u0648 \u067e\u0627\u0631\u06af\u06cc \u06a9\u06cc\u0633\u0647\u0654 \u0622\u0628 \u062f\u0631 \u0645\u0639\u0627\u06cc\u0646\u0647: \u0633\u0642\u0637 \u0627\u062c\u062a\u0646\u0627\u0628\u200c\u0646\u0627\u067e\u0630\u06cc\u0631.",
   "interpretation": "\u0648\u0642\u062a\u06cc \u062f\u0647\u0627\u0646\u0647\u0654 \u0631\u062d\u0645 \u0628\u0627\u0632 \u0627\u0633\u062a \u0648 \u0645\u062d\u0635\u0648\u0644\u0627\u062a \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u06cc\u0627 \u06a9\u06cc\u0633\u0647\u0654 \u0622\u0628 \u062f\u0631 \u062f\u0647\u0627\u0646\u0647 \u062f\u06cc\u062f\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f \u0648 \u067e\u0631\u062f\u0647\u200c\u0647\u0627 \u067e\u0627\u0631\u0647 \u0645\u06cc\u200c\u0634\u0648\u0646\u062f\u060c \u0641\u0631\u0627\u06cc\u0646\u062f \u0633\u0642\u0637 \u0628\u0631\u06af\u0634\u062a\u200c\u0646\u0627\u067e\u0630\u06cc\u0631 \u0648 \u00ab\u0627\u062c\u062a\u0646\u0627\u0628\u200c\u0646\u0627\u067e\u0630\u06cc\u0631\u00bb \u0627\u0633\u062a. \u0633\u0642\u0637 \u062a\u0647\u062f\u06cc\u062f\u06a9\u0646\u0646\u062f\u0647 \u0628\u0627 \u062f\u0647\u0627\u0646\u0647\u0654 \u0628\u0633\u062a\u0647 \u0648 \u067e\u0631\u062f\u0647\u0654 \u0633\u0627\u0644\u0645 \u062a\u0639\u0631\u06cc\u0641 \u0645\u06cc\u200c\u0634\u0648\u062f\u060c \u0633\u0642\u0637 \u0646\u0627\u0642\u0635 \u067e\u0633 \u0627\u0632 \u062e\u0631\u0648\u062c \u0642\u0633\u0645\u062a\u06cc \u0627\u0632 \u0645\u062d\u0635\u0648\u0644\u0627\u062a \u0648 \u0628\u0627\u0642\u06cc\u200c\u0645\u0627\u0646\u062f\u0646 \u0628\u0642\u06cc\u0647 \u0631\u062e \u0645\u06cc\u200c\u062f\u0647\u062f \u0648 \u0633\u0642\u0637 \u0641\u0631\u0627\u0645\u0648\u0634\u200c\u0634\u062f\u0647 \u0628\u0627 \u0645\u0631\u06af \u062c\u0646\u06cc\u0646 \u0628\u062f\u0648\u0646 \u0639\u0644\u0627\u0626\u0645 \u062e\u0631\u0648\u062c \u0647\u0645\u0631\u0627\u0647 \u0627\u0633\u062a.",
   "reasons": ["\u0633\u0642\u0637 \u062a\u0647\u062f\u06cc\u062f\u06a9\u0646\u0646\u062f\u0647 \u0628\u0627 \u062f\u0647\u0627\u0646\u0647\u0654 \u0628\u0633\u062a\u0647 \u0648 \u067e\u0631\u062f\u0647\u0654 \u0633\u0627\u0644\u0645 \u0647\u0645\u0631\u0627\u0647 \u0627\u0633\u062a.", "\u0628\u0627\u0632 \u0628\u0648\u062f\u0646 \u062f\u0647\u0627\u0646\u0647\u0654 \u0631\u062d\u0645 \u0628\u0627 \u062e\u0631\u0648\u062c \u0645\u062d\u062a\u0648\u06cc\u0627\u062a\u060c \u0633\u0642\u0637 \u0627\u062c\u062a\u0646\u0627\u0628\u200c\u0646\u0627\u067e\u0630\u06cc\u0631 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0633\u0642\u0637 \u0646\u0627\u0642\u0635 \u067e\u0633 \u0627\u0632 \u062e\u0631\u0648\u062c \u0642\u0633\u0645\u062a\u06cc \u0627\u0632 \u0645\u062d\u0635\u0648\u0644\u0627\u062a \u0645\u0637\u0631\u062d \u0645\u06cc\u200c\u0634\u0648\u062f.", "\u0633\u0642\u0637 \u0641\u0631\u0627\u0645\u0648\u0634\u200c\u0634\u062f\u0647 \u0628\u0627 \u062c\u0646\u06cc\u0646 \u0641\u0648\u062a\u200c\u0634\u062f\u0647 \u0648 \u062f\u0647\u0627\u0646\u0647\u0654 \u0628\u0633\u062a\u0647 \u062a\u0639\u0631\u06cc\u0641 \u0645\u06cc\u200c\u0634\u0648\u062f."],
  },
  (28, 212): {
   "topic": "earlyDecelOCT",
   "lead": "\u0627\u0641\u062a \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u062c\u0646\u06cc\u0646 \u0647\u0645\u200c\u0632\u0645\u0627\u0646 \u0628\u0627 \u0634\u0631\u0648\u0639 \u0627\u0646\u0642\u0628\u0627\u0636 \u0648 \u0628\u0627\u0632\u06af\u0634\u062a \u0628\u0627 \u067e\u0627\u06cc\u0627\u0646 \u0622\u0646: \u0627\u0641\u062a \u0632\u0648\u062f\u0631\u0633.",
   "interpretation": "\u0627\u0641\u062a \u0632\u0648\u062f\u0631\u0633 \u0627\u0632 \u0634\u0631\u0648\u0639 \u0627\u0646\u0642\u0628\u0627\u0636 \u0622\u063a\u0627\u0632 \u0648 \u0628\u0627 \u067e\u0627\u06cc\u0627\u0646 \u0627\u0646\u0642\u0628\u0627\u0636 \u0628\u0631\u0645\u06cc\u200c\u06af\u0631\u062f\u062f \u0648 \u0622\u06cc\u0646\u0647\u200c\u0648\u0627\u0631 \u0627\u0646\u0642\u0628\u0627\u0636 \u0627\u0633\u062a\u061b \u0633\u0627\u0632\u0648\u06a9\u0627\u0631 \u0622\u0646 \u0641\u0634\u0627\u0631 \u0633\u0631 \u062c\u0646\u06cc\u0646 \u0648 \u062a\u062d\u0631\u06cc\u06a9 \u0648\u0627\u06af \u0627\u0633\u062a \u0648 \u0628\u0647\u200c\u062e\u0648\u062f\u06cc\u200c\u062e\u0648\u062f \u0646\u06af\u0631\u0627\u0646\u200c\u06a9\u0646\u0646\u062f\u0647 \u0646\u06cc\u0633\u062a. \u0627\u0641\u062a \u062f\u06cc\u0631\u0631\u0633 \u067e\u0633 \u0627\u0632 \u0634\u0631\u0648\u0639 \u0627\u0646\u0642\u0628\u0627\u0636 \u0622\u063a\u0627\u0632 \u0648 \u067e\u0633 \u0627\u0632 \u067e\u0627\u06cc\u0627\u0646 \u0622\u0646 \u062a\u0645\u0627\u0645 \u0645\u06cc\u200c\u0634\u0648\u062f\u060c \u0627\u0641\u062a \u0645\u062a\u063a\u06cc\u0631 \u0634\u06a9\u0644 \u0646\u0627\u0645\u0646\u0638\u0645 \u0648 \u0628\u062f\u0648\u0646 \u0627\u0631\u062a\u0628\u0627\u0637 \u062b\u0627\u0628\u062a \u0628\u0627 \u0627\u0646\u0642\u0628\u0627\u0636 \u062f\u0627\u0631\u062f \u0648 \u0627\u0641\u062a \u0637\u0648\u0644\u0627\u0646\u06cc\u200c\u0645\u062f\u062a \u0628\u06cc\u0634 \u0627\u0632 \u062f\u0648 \u062f\u0642\u06cc\u0642\u0647 \u0637\u0648\u0644 \u0645\u06cc\u200c\u06a9\u0634\u062f.",
   "reasons": ["\u0627\u0641\u062a \u0647\u0645\u200c\u0632\u0645\u0627\u0646 \u0628\u0627 \u0627\u0646\u0642\u0628\u0627\u0636 \u0648 \u0628\u0627\u0632\u06af\u0634\u062a \u0628\u0627 \u067e\u0627\u06cc\u0627\u0646 \u0622\u0646\u060c \u0627\u0641\u062a \u0632\u0648\u062f\u0631\u0633 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0627\u0641\u062a \u0645\u062a\u063a\u06cc\u0631 \u0627\u0644\u06af\u0648\u06cc \u0646\u0627\u0645\u0646\u0638\u0645 \u0648 \u0645\u0633\u062a\u0642\u0644 \u0627\u0632 \u0627\u0646\u0642\u0628\u0627\u0636 \u062f\u0627\u0631\u062f.", "\u0627\u0641\u062a \u062f\u06cc\u0631\u0631\u0633 \u067e\u0633 \u0627\u0632 \u067e\u0627\u06cc\u0627\u0646 \u0627\u0646\u0642\u0628\u0627\u0636 \u0628\u0631\u0645\u06cc\u200c\u06af\u0631\u062f\u062f \u0646\u0647 \u0628\u0627 \u067e\u0627\u06cc\u0627\u0646 \u0622\u0646.", "\u0627\u0641\u062a \u0637\u0648\u0644\u0627\u0646\u06cc\u200c\u0645\u062f\u062a \u0628\u06cc\u0634 \u0627\u0632 \u062f\u0648 \u062f\u0642\u06cc\u0642\u0647 \u0627\u062f\u0627\u0645\u0647 \u0645\u06cc\u200c\u06cc\u0627\u0628\u062f."],
  },
  (28, 213): {
   "topic": "endometriosisDiagnosis",
   "lead": "\u0646\u062f\u0648\u0644\u200c\u0647\u0627\u06cc \u0633\u067e\u062a\u0648\u0645 \u0631\u06a9\u062a\u0648\u0648\u0627\u0698\u06cc\u0646\u0627\u0644 \u0648 \u0631\u062d\u0645 \u0631\u062a\u0631\u0648\u0648\u0631\u062a \u0648 \u0641\u06cc\u06a9\u0633: \u0644\u0627\u067e\u0627\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u0631\u0648\u0634 \u0627\u0631\u062c\u062d \u062a\u0634\u062e\u06cc\u0635 \u0627\u0633\u062a.",
   "interpretation": "\u06cc\u0627\u0641\u062a\u0647\u200c\u0647\u0627\u06cc \u0645\u0639\u0627\u06cc\u0646\u0647 (\u0631\u062d\u0645 \u0631\u062a\u0631\u0648\u0648\u0631\u062a \u0648 \u0641\u06cc\u06a9\u0633\u200c\u0634\u062f\u0647 \u0648 \u0646\u062f\u0648\u0644\u200c\u0647\u0627\u06cc \u0633\u067e\u062a\u0648\u0645 \u0631\u06a9\u062a\u0648\u0648\u0627\u0698\u06cc\u0646\u0627\u0644) \u0628\u0647 \u0627\u0646\u062f\u0648\u0645\u062a\u0631\u06cc\u0648\u0632 \u0639\u0645\u0642\u06cc \u0627\u0634\u0627\u0631\u0647 \u062f\u0627\u0631\u062f \u0648 \u0644\u0627\u067e\u0627\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u0628\u0627 \u0645\u0634\u0627\u0647\u062f\u0647\u0654 \u0645\u0633\u062a\u0642\u06cc\u0645 \u0648 \u0646\u0645\u0648\u0646\u0647\u200c\u0628\u0631\u062f\u0627\u0631\u06cc\u060c \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u0642\u0637\u0639\u06cc \u062a\u0634\u062e\u06cc\u0635 \u0627\u0633\u062a. \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u062a\u0631\u0627\u0646\u0633\u200c\u0648\u0627\u0698\u06cc\u0646\u0627\u0644 \u06a9\u0645\u06a9\u200c\u06a9\u0646\u0646\u062f\u0647 \u0627\u0633\u062a \u0648\u0644\u06cc \u062a\u0634\u062e\u06cc\u0635 \u0631\u0627 \u0642\u0637\u0639\u06cc \u0646\u0645\u06cc\u200c\u06a9\u0646\u062f\u060c \u0647\u06cc\u0633\u062a\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u0641\u0642\u0637 \u062f\u0627\u062e\u0644 \u062d\u0641\u0631\u0647\u0654 \u0631\u062d\u0645 \u0631\u0627 \u0645\u06cc\u200c\u0628\u06cc\u0646\u062f \u0648 CA125 \u062d\u0633\u0627\u0633\u06cc\u062a \u0648 \u0648\u06cc\u0698\u06af\u06cc \u06a9\u0627\u0641\u06cc \u0646\u062f\u0627\u0631\u062f.",
   "reasons": ["\u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u062a\u0631\u0627\u0646\u0633\u200c\u0648\u0627\u0698\u06cc\u0646\u0627\u0644 \u06a9\u0645\u06a9\u200c\u06a9\u0646\u0646\u062f\u0647 \u0627\u0633\u062a \u0648\u0644\u06cc \u062a\u0634\u062e\u06cc\u0635 \u0642\u0637\u0639\u06cc \u0646\u0645\u06cc\u200c\u062f\u0647\u062f.", "\u0644\u0627\u067e\u0627\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u0642\u0637\u0639\u06cc \u062a\u0634\u062e\u06cc\u0635 \u0627\u0646\u062f\u0648\u0645\u062a\u0631\u06cc\u0648\u0632 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0647\u06cc\u0633\u062a\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u062a\u0646\u0647\u0627 \u062d\u0641\u0631\u0647\u0654 \u0631\u062d\u0645 \u0631\u0627 \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u0645\u06cc\u200c\u06a9\u0646\u062f.", "CA125 \u0646\u0647 \u062d\u0633\u0627\u0633\u06cc\u062a \u06a9\u0627\u0641\u06cc \u062f\u0627\u0631\u062f \u0648 \u0646\u0647 \u0648\u06cc\u0698\u06af\u06cc \u0627\u062e\u062a\u0635\u0627\u0635\u06cc."],
  },
  (28, 214): {
   "topic": "prom35wInduction",
   "lead": "\u067e\u0627\u0631\u06af\u06cc \u067e\u0631\u062f\u0647\u200c\u0647\u0627 \u0627\u0632 \u062f\u0648 \u0631\u0648\u0632 \u0642\u0628\u0644 \u062f\u0631 \u06f3\u06f5 \u0647\u0641\u062a\u0647 \u0628\u0627 \u0646\u0645\u0627\u06cc\u0634 \u0633\u0641\u0627\u0644\u06cc\u06a9: \u062a\u062d\u0631\u06cc\u06a9 \u0632\u0627\u06cc\u0645\u0627\u0646.",
   "interpretation": "\u067e\u0633 \u0627\u0632 \u067e\u0627\u0631\u06af\u06cc \u067e\u0631\u062f\u0647\u200c\u0647\u0627 \u062e\u0637\u0631 \u0639\u0641\u0648\u0646\u062a \u0635\u0639\u0648\u062f\u06cc \u0628\u0627 \u06af\u0630\u0634\u062a \u0632\u0645\u0627\u0646 \u0628\u0627\u0644\u0627 \u0645\u06cc\u200c\u0631\u0648\u062f \u0648 \u062f\u0631 \u06f3\u06f5 \u0647\u0641\u062a\u0647 \u06a9\u0647 \u062c\u0646\u06cc\u0646 \u0646\u0632\u062f\u06cc\u06a9 \u062a\u0631\u0645 \u0627\u0633\u062a\u060c \u062e\u062a\u0645 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0628\u0627 \u062a\u062d\u0631\u06cc\u06a9 \u0632\u0627\u06cc\u0645\u0627\u0646 \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u0627\u0633\u062a\u061b \u0633\u0632\u0627\u0631\u06cc\u0646 \u0641\u0648\u0631\u06cc \u062f\u0631 \u0646\u0628\u0648\u062f \u0627\u0646\u062f\u06cc\u06a9\u0627\u0633\u06cc\u0648\u0646 \u0645\u0627\u0645\u0627\u06cc\u06cc \u0644\u0627\u0632\u0645 \u0646\u06cc\u0633\u062a\u060c \u06a9\u0648\u0631\u062a\u06cc\u06a9\u0648\u0627\u0633\u062a\u0631\u0648\u0626\u06cc\u062f \u0628\u0627 \u062a\u0635\u0645\u06cc\u0645 \u0628\u0647 \u062e\u062a\u0645 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0627\u0648\u0644\u0648\u06cc\u062a \u0646\u062f\u0627\u0631\u062f \u0648 \u062a\u0648\u06a9\u0648\u0644\u06cc\u062a\u06cc\u06a9 \u062f\u0631 \u062d\u0636\u0648\u0631 \u067e\u0627\u0631\u06af\u06cc \u0645\u0632\u0645\u0646 \u067e\u0631\u062f\u0647\u200c\u0647\u0627 \u062e\u0637\u0631 \u0639\u0641\u0648\u0646\u062a \u0631\u0627 \u0628\u0627\u0644\u0627 \u0645\u06cc\u200c\u0628\u0631\u062f.",
   "reasons": ["\u062f\u0631 \u067e\u0627\u0631\u06af\u06cc \u067e\u0631\u062f\u0647\u200c\u0647\u0627 \u0646\u0632\u062f\u06cc\u06a9 \u062a\u0631\u0645 \u0628\u0627 \u0646\u0645\u0627\u06cc\u0634 \u0633\u0641\u0627\u0644\u06cc\u06a9\u060c \u062a\u062d\u0631\u06cc\u06a9 \u0632\u0627\u06cc\u0645\u0627\u0646 \u062a\u0648\u0635\u06cc\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0633\u0632\u0627\u0631\u06cc\u0646 \u0641\u0648\u0631\u06cc \u062f\u0631 \u0646\u0628\u0648\u062f \u0627\u0646\u062f\u06cc\u06a9\u0627\u0633\u06cc\u0648\u0646 \u0645\u0627\u0645\u0627\u06cc\u06cc \u0644\u0627\u0632\u0645 \u0646\u06cc\u0633\u062a.", "\u06a9\u0648\u0631\u062a\u06cc\u06a9\u0648\u0627\u0633\u062a\u0631\u0648\u0626\u06cc\u062f \u062f\u0631 \u0627\u06cc\u0646 \u0645\u0631\u062d\u0644\u0647 \u0628\u0627 \u062a\u0635\u0645\u06cc\u0645 \u0628\u0647 \u062e\u062a\u0645 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0627\u0648\u0644\u0648\u06cc\u062a \u0646\u062f\u0627\u0631\u062f.", "\u062a\u0648\u06a9\u0648\u0644\u06cc\u062a\u06cc\u06a9 \u062f\u0631 \u062d\u0636\u0648\u0631 \u067e\u0627\u0631\u06af\u06cc \u067e\u0631\u062f\u0647\u200c\u0647\u0627 \u062e\u0637\u0631 \u0639\u0641\u0648\u0646\u062a \u0631\u0627 \u0628\u0627\u0644\u0627 \u0645\u06cc\u200c\u0628\u0631\u062f."],
  },
  (28, 215): {
   "topic": "mildPreeclampsiaDefinition",
   "lead": "\u0641\u0634\u0627\u0631 \u06f1\u06f4\u06f0/\u06f9\u06f0 \u0648 \u062f\u0641\u0639 \u06f3\u06f5\u06f0 \u0645\u06cc\u0644\u06cc\u200c\u06af\u0631\u0645 \u067e\u0631\u0648\u062a\u0626\u06cc\u0646 \u062f\u0631 \u06f2\u06f4 \u0633\u0627\u0639\u062a \u0628\u062f\u0648\u0646 \u0633\u0627\u0628\u0642\u0647\u0654 \u0641\u0634\u0627\u0631 \u062e\u0648\u0646: \u067e\u0631\u0647\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u062e\u0641\u06cc\u0641.",
   "interpretation": "\u067e\u0631\u0647\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u062e\u0641\u06cc\u0641 \u0628\u0627 \u0641\u0634\u0627\u0631 \u06f1\u06f4\u06f0/\u06f9\u06f0 \u06cc\u0627 \u0628\u0627\u0644\u0627\u062a\u0631 \u067e\u0633 \u0627\u0632 \u0647\u0641\u062a\u0647\u0654 \u06f2\u06f0 \u0647\u0645\u0631\u0627\u0647 \u0628\u0627 \u067e\u0631\u0648\u062a\u0626\u06cc\u0646\u0648\u0631\u06cc \u06f3\u06f0\u06f0 \u0645\u06cc\u0644\u06cc\u200c\u06af\u0631\u0645 \u06cc\u0627 \u0628\u06cc\u0634\u062a\u0631 \u062f\u0631 \u06f2\u06f4 \u0633\u0627\u0639\u062a \u062f\u0631 \u0632\u0646\u06cc \u06a9\u0647 \u067e\u06cc\u0634\u200c\u062a\u0631 \u0641\u0634\u0627\u0631 \u062e\u0648\u0646 \u0646\u062f\u0627\u0634\u062a\u0647 \u062a\u0639\u0631\u06cc\u0641 \u0645\u06cc\u200c\u0634\u0648\u062f. \u0641\u0634\u0627\u0631 \u062e\u0648\u0646 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u067e\u0631\u0648\u062a\u0626\u06cc\u0646\u0648\u0631\u06cc \u0646\u062f\u0627\u0631\u062f\u060c \u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u0628\u0627 \u062a\u0634\u0646\u062c \u0634\u0646\u0627\u062e\u062a\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f \u0648 \u067e\u0631\u0647\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u0641\u0648\u0642\u200c\u0627\u0641\u0632\u0648\u062f\u0647 \u062f\u0631 \u0628\u0633\u062a\u0631 \u067e\u0631\u0641\u0634\u0627\u0631\u06cc \u062e\u0648\u0646 \u0645\u0632\u0645\u0646 \u0642\u0628\u0644\u06cc \u0631\u062e \u0645\u06cc\u200c\u062f\u0647\u062f.",
   "reasons": ["\u0641\u0634\u0627\u0631 \u062e\u0648\u0646 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u067e\u0631\u0648\u062a\u0626\u06cc\u0646\u0648\u0631\u06cc \u0646\u062f\u0627\u0631\u062f \u0648 \u0627\u06cc\u0646\u200c\u062c\u0627 \u06f3\u06f5\u06f0 \u0645\u06cc\u0644\u06cc\u200c\u06af\u0631\u0645 \u062f\u0641\u0639 \u0634\u062f\u0647 \u0627\u0633\u062a.", "\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u0628\u0627 \u062a\u0634\u0646\u062c \u062a\u0639\u0631\u06cc\u0641 \u0645\u06cc\u200c\u0634\u0648\u062f \u06a9\u0647 \u062f\u0631 \u0627\u06cc\u0646 \u0628\u06cc\u0645\u0627\u0631 \u0648\u062c\u0648\u062f \u0646\u062f\u0627\u0631\u062f.", "\u067e\u0631\u0647\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u062e\u0641\u06cc\u0641 \u0628\u0627 \u0627\u06cc\u0646 \u0645\u0639\u06cc\u0627\u0631\u0647\u0627 \u0645\u0637\u0627\u0628\u0642\u062a \u062f\u0627\u0631\u062f\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u067e\u0631\u0647\u0627\u06a9\u0644\u0627\u0645\u067e\u0633\u06cc \u0641\u0648\u0642\u200c\u0627\u0641\u0632\u0648\u062f\u0647 \u0646\u06cc\u0627\u0632\u0645\u0646\u062f \u0633\u0627\u0628\u0642\u0647\u0654 \u0641\u0634\u0627\u0631 \u062e\u0648\u0646 \u0645\u0632\u0645\u0646 \u0627\u0633\u062a."],
  },
  (28, 216): {
   "topic": "pmbEndometrialBiopsy",
   "lead": "\u0645\u0646\u0648\u0645\u062a\u0631\u0648\u0631\u0627\u0698\u06cc \u062f\u0631 \u0632\u0646 \u06f3\u06f6 \u0633\u0627\u0644\u0647\u0654 \u0686\u0627\u0642 \u0628\u0627 \u0636\u062e\u0627\u0645\u062a \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u06f1\u06f2 \u0645\u06cc\u0644\u06cc\u200c\u0645\u062a\u0631: \u0628\u06cc\u0648\u067e\u0633\u06cc \u0622\u0646\u062f\u0648\u0645\u062a\u0631.",
   "interpretation": "\u062f\u0631 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u063a\u06cc\u0631\u0637\u0628\u06cc\u0639\u06cc \u0631\u062d\u0645\u06cc \u0628\u0627 \u0636\u062e\u0627\u0645\u062a \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u0628\u06cc\u0634 \u0627\u0632 \u06f1\u06f0 \u062a\u0627 \u06f1\u06f2 \u0645\u06cc\u0644\u06cc\u200c\u0645\u062a\u0631\u060c \u0628\u0647\u200c\u0648\u06cc\u0698\u0647 \u0647\u0645\u0631\u0627\u0647 \u0686\u0627\u0642\u06cc \u06a9\u0647 \u062e\u0637\u0631 \u0647\u0627\u06cc\u067e\u0631\u067e\u0644\u0627\u0632\u06cc \u0648 \u0628\u062f\u062e\u06cc\u0645\u06cc \u0631\u0627 \u0628\u0627\u0644\u0627 \u0645\u06cc\u200c\u0628\u0631\u062f\u060c \u0628\u06cc\u0648\u067e\u0633\u06cc \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u0628\u0631\u0627\u06cc \u0631\u062f \u0647\u0627\u06cc\u067e\u0631\u067e\u0644\u0627\u0632\u06cc \u0642\u062f\u0645 \u0627\u0648\u0644 \u0627\u0633\u062a. \u062a\u062c\u0648\u06cc\u0632 \u067e\u0631\u0648\u0698\u0633\u062a\u0631\u0648\u0646 \u062f\u0648\u0631\u0647\u200c\u0627\u06cc \u06cc\u0627 \u0642\u0631\u0635 \u0636\u062f\u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u067e\u06cc\u0634 \u0627\u0632 \u0631\u062f \u0636\u0627\u06cc\u0639\u0647\u0654 \u0633\u0627\u062e\u062a\u0627\u0631\u06cc \u062f\u0631\u0645\u0627\u0646 \u06a9\u0648\u0631 \u0645\u062d\u0633\u0648\u0628 \u0645\u06cc\u200c\u0634\u0648\u062f \u0648 \u0647\u06cc\u0633\u062a\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u067e\u0633 \u0627\u0632 \u0628\u06cc\u0648\u067e\u0633\u06cc \u06cc\u0627 \u062f\u0631 \u0636\u0627\u06cc\u0639\u0647\u0654 \u06a9\u0627\u0646\u0648\u0646\u06cc \u062c\u0627\u06cc \u062f\u0627\u0631\u062f.",
   "reasons": ["\u0628\u06cc\u0648\u067e\u0633\u06cc \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u0627\u0648\u0644\u06cc\u0646 \u0627\u0642\u062f\u0627\u0645 \u0628\u0631\u0627\u06cc \u0631\u062f \u0647\u0627\u06cc\u067e\u0631\u067e\u0644\u0627\u0632\u06cc \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u067e\u0631\u0648\u0698\u0633\u062a\u0631\u0648\u0646 \u062f\u0648\u0631\u0647\u200c\u0627\u06cc \u067e\u06cc\u0634 \u0627\u0632 \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u0628\u0627\u0641\u062a \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u062f\u0631\u0645\u0627\u0646 \u06a9\u0648\u0631 \u0627\u0633\u062a.", "\u0642\u0631\u0635 \u0636\u062f\u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u067e\u06cc\u0634 \u0627\u0632 \u0631\u062f \u0628\u062f\u062e\u06cc\u0645\u06cc \u062f\u0631\u0645\u0627\u0646 \u0645\u0646\u0627\u0633\u0628 \u0646\u06cc\u0633\u062a.", "\u0647\u06cc\u0633\u062a\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u067e\u0633 \u0627\u0632 \u0628\u06cc\u0648\u067e\u0633\u06cc \u06cc\u0627 \u062f\u0631 \u0636\u0627\u06cc\u0639\u0647\u0654 \u06a9\u0627\u0646\u0648\u0646\u06cc \u0645\u0637\u0631\u062d \u0645\u06cc\u200c\u0634\u0648\u062f."],
  },
  (28, 217): {
   "topic": "primaryAmenorrheaNoPuberty",
   "lead": "\u0622\u0645\u0646\u0648\u0631\u0647\u0654 \u0627\u0648\u0644\u06cc\u0647 \u0647\u0645\u0631\u0627\u0647 \u0628\u0627 \u0639\u062f\u0645 \u0628\u0631\u0648\u0632 \u0635\u0641\u0627\u062a \u062b\u0627\u0646\u0648\u06cc\u0647\u0654 \u062c\u0646\u0633\u06cc: \u0646\u0627\u0631\u0633\u0627\u06cc\u06cc \u062a\u062e\u0645\u062f\u0627\u0646 \u0634\u0627\u06cc\u0639\u200c\u062a\u0631\u06cc\u0646 \u0639\u0644\u062a \u0627\u0633\u062a.",
   "interpretation": "\u062f\u0631 \u062f\u062e\u062a\u0631\u06cc \u06a9\u0647 \u0646\u0647 \u0645\u0646\u0627\u0631\u06a9 \u062f\u0627\u0634\u062a\u0647 \u0648 \u0646\u0647 \u0635\u0641\u0627\u062a \u062b\u0627\u0646\u0648\u06cc\u0647\u0654 \u062c\u0646\u0633\u06cc \u0628\u0631\u0648\u0632 \u06a9\u0631\u062f\u0647\u060c \u0645\u0646\u0634\u0623 \u0627\u062e\u062a\u0644\u0627\u0644 \u062f\u0631 \u062a\u062e\u0645\u062f\u0627\u0646 (\u0646\u0627\u0631\u0633\u0627\u06cc\u06cc \u062a\u062e\u0645\u062f\u0627\u0646\u06cc \u06cc\u0627 \u062f\u06cc\u0633\u200c\u0698\u0646\u0632\u06cc \u06af\u0646\u0627\u062f) \u0634\u0627\u06cc\u0639\u200c\u062a\u0631\u06cc\u0646 \u0639\u0644\u062a \u0627\u0633\u062a\u061b \u0646\u0628\u0648\u062f \u0645\u0627\u062f\u0631\u0632\u0627\u062f\u06cc \u0631\u062d\u0645 \u0645\u0639\u0645\u0648\u0644\u0627\u064b \u0628\u0627 \u0628\u0631\u0648\u0632 \u0637\u0628\u06cc\u0639\u06cc \u0635\u0641\u0627\u062a \u062b\u0627\u0646\u0648\u06cc\u0647 \u0647\u0645\u0631\u0627\u0647 \u0627\u0633\u062a\u060c \u0627\u062e\u062a\u0644\u0627\u0644 \u0647\u06cc\u067e\u0648\u0641\u06cc\u0632\u06cc \u0646\u0627\u062f\u0631\u062a\u0631 \u0627\u0633\u062a \u0648 \u0633\u067e\u062a\u0648\u0645 \u0627\u0646\u0633\u062f\u0627\u062f\u06cc \u0648\u0627\u0698\u0646 \u0628\u0627 \u0627\u062d\u062a\u0628\u0627\u0633 \u062e\u0648\u0646 \u0648 \u0628\u0631\u0648\u0632 \u0637\u0628\u06cc\u0639\u06cc \u0635\u0641\u0627\u062a \u062b\u0627\u0646\u0648\u06cc\u0647 \u062a\u0638\u0627\u0647\u0631 \u0645\u06cc\u200c\u06a9\u0646\u062f.",
   "reasons": ["\u0646\u0627\u0631\u0633\u0627\u06cc\u06cc \u062a\u062e\u0645\u062f\u0627\u0646 \u0634\u0627\u06cc\u0639\u200c\u062a\u0631\u06cc\u0646 \u0639\u0644\u062a \u0622\u0645\u0646\u0648\u0631\u0647\u0654 \u0627\u0648\u0644\u06cc\u0647 \u0628\u0627 \u0639\u062f\u0645 \u0628\u0644\u0648\u063a \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0646\u0628\u0648\u062f \u0645\u0627\u062f\u0631\u0632\u0627\u062f\u06cc \u0631\u062d\u0645 \u0645\u0639\u0645\u0648\u0644\u0627\u064b \u0628\u0627 \u0635\u0641\u0627\u062a \u062b\u0627\u0646\u0648\u06cc\u0647\u0654 \u0637\u0628\u06cc\u0639\u06cc \u0647\u0645\u0631\u0627\u0647 \u0627\u0633\u062a.", "\u0627\u062e\u062a\u0644\u0627\u0644 \u0647\u06cc\u067e\u0648\u0641\u06cc\u0632\u06cc \u0639\u0644\u062a \u0646\u0627\u062f\u0631\u062a\u0631\u06cc \u0628\u0631\u0627\u06cc \u0627\u06cc\u0646 \u062a\u0627\u0628\u0644\u0648 \u0627\u0633\u062a.", "\u0633\u067e\u062a\u0648\u0645 \u0627\u0646\u0633\u062f\u0627\u062f\u06cc \u0648\u0627\u0698\u0646 \u0628\u0627 \u0628\u0631\u0648\u0632 \u0637\u0628\u06cc\u0639\u06cc \u0635\u0641\u0627\u062a \u062b\u0627\u0646\u0648\u06cc\u0647 \u0648 \u0627\u062d\u062a\u0628\u0627\u0633 \u062e\u0648\u0646 \u0647\u0645\u0631\u0627\u0647 \u0627\u0633\u062a."],
  },
  (28, 219): {
   "topic": "completeMoleKaryotype",
   "lead": "\u0634\u0627\u06cc\u0639\u200c\u062a\u0631\u06cc\u0646 \u06a9\u0627\u0631\u06cc\u0648\u062a\u0627\u06cc\u067e \u0645\u0648\u0644 \u06a9\u0627\u0645\u0644 \u06f4\u06f6XX \u0627\u0633\u062a\u060c \u0646\u0647 \u06f4\u06f6XY.",
   "interpretation": "\u0645\u0648\u0644 \u06a9\u0627\u0645\u0644 \u0627\u0632 \u0644\u0642\u0627\u062d \u062a\u062e\u0645\u06a9 \u0628\u062f\u0648\u0646 \u0645\u0627\u062f\u0647\u0654 \u0698\u0646\u062a\u06cc\u06a9\u06cc \u0628\u0627 \u06cc\u06a9 \u0627\u0633\u067e\u0631\u0645 \u0647\u0627\u067e\u0644\u0648\u0626\u06cc\u062f \u0648 \u0633\u067e\u0633 \u062a\u06a9\u062b\u06cc\u0631 \u06a9\u0631\u0648\u0645\u0648\u0632\u0648\u0645 \u067e\u062f\u0631\u06cc (reduplication) \u0627\u06cc\u062c\u0627\u062f \u0645\u06cc\u200c\u0634\u0648\u062f\u061b \u0634\u0627\u06cc\u0639\u200c\u062a\u0631\u06cc\u0646 \u06a9\u0627\u0631\u06cc\u0648\u062a\u0627\u06cc\u067e \u0622\u0646 \u06f4\u06f6XX \u0627\u0633\u062a \u0648 \u06f4\u06f6XY \u062f\u0631 \u0646\u0633\u0628\u062a \u06a9\u0645\u200c\u062a\u0631\u06cc \u062f\u06cc\u062f\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f\u060c \u0628\u0646\u0627\u0628\u0631\u0627\u06cc\u0646 \u0627\u062f\u0639\u0627\u06cc \u00ab\u0634\u0627\u06cc\u0639\u200c\u062a\u0631\u06cc\u0646 \u06a9\u0627\u0631\u06cc\u0648\u062a\u0627\u06cc\u067e \u06f4\u06f6XY\u00bb \u0646\u0627\u062f\u0631\u0633\u062a \u0627\u0633\u062a. \u062f\u0631 \u0645\u0648\u0644 \u06a9\u0627\u0645\u0644 \u0628\u0627\u0641\u062a \u062c\u0646\u06cc\u0646\u06cc \u062f\u06cc\u062f\u0647 \u0646\u0645\u06cc\u200c\u0634\u0648\u062f \u0648 \u0634\u0627\u06cc\u0639\u200c\u062a\u0631\u06cc\u0646 \u0646\u0634\u0627\u0646\u0647\u0654 \u0628\u0627\u0644\u06cc\u0646\u06cc \u0622\u0646 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u0648\u0627\u0698\u06cc\u0646\u0627\u0644 \u0627\u0633\u062a.",
   "reasons": ["\u0634\u0627\u06cc\u0639\u200c\u062a\u0631\u06cc\u0646 \u06a9\u0627\u0631\u06cc\u0648\u062a\u0627\u06cc\u067e \u0645\u0648\u0644 \u06a9\u0627\u0645\u0644 \u06f4\u06f6XX \u0627\u0633\u062a \u0648 \u0627\u062f\u0639\u0627\u06cc \u06f4\u06f6XY \u0646\u0627\u062f\u0631\u0633\u062a \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u062f\u0631 \u0645\u0648\u0644 \u06a9\u0627\u0645\u0644 \u0628\u0627\u0641\u062a \u062c\u0646\u06cc\u0646\u06cc \u062f\u06cc\u062f\u0647 \u0646\u0645\u06cc\u200c\u0634\u0648\u062f\u061b \u0627\u06cc\u0646 \u0639\u0628\u0627\u0631\u062a \u062f\u0631\u0633\u062a \u0627\u0633\u062a.", "\u0634\u0627\u06cc\u0639\u200c\u062a\u0631\u06cc\u0646 \u0646\u0634\u0627\u0646\u0647\u0654 \u0628\u0627\u0644\u06cc\u0646\u06cc \u0645\u0648\u0644 \u06a9\u0627\u0645\u0644 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u0648\u0627\u0698\u06cc\u0646\u0627\u0644 \u0627\u0633\u062a\u061b \u0627\u06cc\u0646 \u0639\u0628\u0627\u0631\u062a \u062f\u0631\u0633\u062a \u0627\u0633\u062a.", "\u0644\u0642\u0627\u062d \u062a\u062e\u0645\u06a9 \u0628\u062f\u0648\u0646 \u0645\u0627\u062f\u0647\u0654 \u0698\u0646\u062a\u06cc\u06a9\u06cc \u0628\u0627 \u0627\u0633\u067e\u0631\u0645 \u0647\u0627\u067e\u0644\u0648\u0626\u06cc\u062f \u0648 \u062a\u06a9\u062b\u06cc\u0631 \u067e\u062f\u0631\u06cc\u060c \u0645\u06a9\u0627\u0646\u06cc\u0632\u0645 \u062f\u0631\u0633\u062a \u0645\u0648\u0644 \u06a9\u0627\u0645\u0644 \u0627\u0633\u062a."],
  },
  (28, 220): {
   "topic": "ocpCancerEffects",
   "lead": "\u0642\u0631\u0635 \u0636\u062f\u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062a\u0631\u06a9\u06cc\u0628\u06cc \u062c\u0632\u0621 \u0639\u0648\u0627\u0645\u0644 \u062e\u0637\u0631 \u0633\u0631\u0637\u0627\u0646 \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u0646\u06cc\u0633\u062a.",
   "interpretation": "\u0645\u0635\u0631\u0641 \u062a\u0627\u0645\u0648\u06a9\u0633\u06cc\u0641\u0646\u060c \u062a\u062e\u0645\u062f\u0627\u0646 \u067e\u0644\u06cc\u200c\u06a9\u06cc\u0633\u062a\u06cc\u06a9 \u0648 \u06cc\u0627\u0626\u0633\u06af\u06cc \u062f\u06cc\u0631\u0631\u0633 (\u067e\u0633 \u0627\u0632 \u06f5\u06f5 \u0633\u0627\u0644\u06af\u06cc) \u0628\u0627 \u0627\u0641\u0632\u0627\u06cc\u0634 \u062e\u0637\u0631 \u0647\u0627\u06cc\u067e\u0631\u067e\u0644\u0627\u0632\u06cc \u0648 \u0633\u0631\u0637\u0627\u0646 \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u0647\u0645\u0631\u0627\u0647\u200c\u0627\u0646\u062f\u061b \u062f\u0631 \u0645\u0642\u0627\u0628\u0644 \u0642\u0631\u0635 \u0636\u062f\u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062a\u0631\u06a9\u06cc\u0628\u06cc \u0628\u0627 \u0645\u0647\u0627\u0631 \u062a\u062e\u0645\u06a9\u200c\u06af\u0630\u0627\u0631\u06cc \u0648 \u06a9\u0627\u0647\u0634 \u0645\u0648\u0627\u062c\u0647\u0647\u0654 \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u0628\u0627 \u0627\u0633\u062a\u0631\u0648\u0698\u0646 \u0628\u062f\u0648\u0646 \u062d\u0631\u06cc\u0641\u060c \u062e\u0637\u0631 \u0633\u0631\u0637\u0627\u0646 \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u0631\u0627 \u06a9\u0627\u0647\u0634 \u0645\u06cc\u200c\u062f\u0647\u062f \u0648 \u0628\u0646\u0627\u0628\u0631\u0627\u06cc\u0646 \u0639\u0627\u0645\u0644 \u062e\u0637\u0631 \u0645\u062d\u0633\u0648\u0628 \u0646\u0645\u06cc\u200c\u0634\u0648\u062f.",
   "reasons": ["\u062a\u0627\u0645\u0648\u06a9\u0633\u06cc\u0641\u0646 \u062e\u0637\u0631 \u0633\u0631\u0637\u0627\u0646 \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u0631\u0627 \u0627\u0641\u0632\u0627\u06cc\u0634 \u0645\u06cc\u200c\u062f\u0647\u062f.", "\u0642\u0631\u0635 \u062a\u0631\u06a9\u06cc\u0628\u06cc \u0636\u062f\u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062e\u0637\u0631 \u0633\u0631\u0637\u0627\u0646 \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u0631\u0627 \u06a9\u0627\u0647\u0634 \u0645\u06cc\u200c\u062f\u0647\u062f\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u062a\u062e\u0645\u062f\u0627\u0646 \u067e\u0644\u06cc\u200c\u06a9\u06cc\u0633\u062a\u06cc\u06a9 \u0628\u0627 \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u0628\u062f\u0648\u0646 \u062d\u0631\u06cc\u0641 \u0648 \u0627\u0641\u0632\u0627\u06cc\u0634 \u062e\u0637\u0631 \u0647\u0645\u0631\u0627\u0647 \u0627\u0633\u062a.", "\u06cc\u0627\u0626\u0633\u06af\u06cc \u067e\u0633 \u0627\u0632 \u06f5\u06f5 \u0633\u0627\u0644\u06af\u06cc \u0645\u0648\u0627\u062c\u0647\u0647\u0654 \u0637\u0648\u0644\u0627\u0646\u06cc \u0627\u0633\u062a\u0631\u0648\u0698\u0646 \u0631\u0627 \u0628\u0627\u0644\u0627 \u0645\u06cc\u200c\u0628\u0631\u062f."],
  },
}
